--
-- Name: absentees_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.absentees_today() RETURNS TABLE(user_id uuid, full_name text, phone text, outlet_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.id, p.full_name, p.phone, o.name
  from public.profiles p
  left join public.outlets o on o.id = p.outlet_id
  where p.is_active
    and public.is_field_role(p.role)
    and (public.is_admin() or public.supervises_user(p.id))
    and not exists (
      select 1 from public.attendance a
      where a.user_id = p.id
        and a.attendance_date = public.business_date()
        and a.type = 'opening'
    )
  order by p.full_name;
$$;


--
-- Name: admin_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_overview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with today as (select public.business_date() as d),
  staff as (
    select p.id, p.full_name, o.shift_start
    from public.profiles p
    left join public.outlets o on o.id = p.outlet_id
    where p.is_active and public.is_field_role(p.role)
  ),
  openings as (
    select a.user_id, a.created_at, a.status
    from public.attendance a, today
    where a.attendance_date = today.d and a.type = 'opening'
  ),
  closings as (
    select a.user_id from public.attendance a, today
    where a.attendance_date = today.d and a.type = 'closing'
  )
  select jsonb_build_object(
    'date',            (select d from today),
    'staff_total',     (select count(*) from staff),
    'clocked_in',      (select count(*) from openings),
    'clocked_out',     (select count(*) from closings),
    'still_on_shift',  (select count(*) from openings o
                        where not exists (select 1 from closings c where c.user_id = o.user_id)),
    'absent',          (select count(*) from staff s
                        where not exists (select 1 from openings o where o.user_id = s.id)),
    'late',            (select count(*) from openings o
                        join staff s on s.id = o.user_id
                        where s.shift_start is not null
                          and (o.created_at at time zone 'Africa/Lagos')::time > s.shift_start),
    'off_site',        (select count(*) from openings where status <> 'on_site'),
    'open_alerts',     (select count(*) from public.location_alerts where not is_resolved)
  )
  where public.is_admin() or public.current_user_role() = 'supervisor';
$$;


--
-- Name: alert_watchers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.alert_watchers(p_user uuid) RETURNS TABLE(user_id uuid, full_name text, role public.user_role)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select w.id, w.full_name, w.role
  from public.profiles w
  join public.profiles them on them.id = p_user
  where w.is_active
    and w.id <> p_user
    and (
      w.role = 'admin'::user_role
      or (
        w.role = 'supervisor'::user_role
        and public.is_field_role(them.role)
        and (
          them.supervisor_id = w.id
          or (w.outlet_id is not null and them.outlet_id = w.outlet_id)
          or (w.outlet_id is not null
              and exists (select 1 from public.staff_outlets s
                          where s.user_id = them.id and s.outlet_id = w.outlet_id))
        )
      )
    );
$$;


--
-- Name: assign_support_thread(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_support_thread(p_thread uuid, p_assignee uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  owner uuid;
begin
  select t.user_id into owner from public.support_threads t where t.id = p_thread;
  if owner is null then raise exception 'No such thread'; end if;
  if not (public.is_admin() or public.supervises_user(owner)) then
    raise exception 'That thread is not yours';
  end if;
  if p_assignee is not null
     and not exists (select 1 from public.alert_watchers(owner) w where w.user_id = p_assignee) then
    raise exception 'That person cannot take this thread';
  end if;
  update public.support_threads
  set assigned_to = p_assignee,
      assigned_at = case when p_assignee is null then null else now() end
  where id = p_thread;
end;
$$;


