--
-- Name: attendance_punctuality(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_punctuality() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  shift record;
  -- When the photo was taken, which is when they clocked: a clock-in made
  -- offline and sent later is not late for having waited for signal.
  -- (A phone clock moved to look punctual is flagged by 026.)
  at_local timestamp := (coalesce(new.client_captured_at, new.created_at) at time zone 'Africa/Lagos');
  minutes integer;
begin
  if new.user_id is null then
    return null;
  end if;

  -- The store they clocked at, or their home store.
  select o.id, o.name, o.shift_start, o.shift_end into shift
  from public.outlets o
  where o.id = coalesce(new.outlet_id,
                        (select p.outlet_id from public.profiles p where p.id = new.user_id));
  if shift.id is null or shift.shift_start is null or shift.shift_end is null then
    return null;
  end if;

  if new.type = 'opening' then
    minutes := floor(extract(epoch from at_local - (new.attendance_date + shift.shift_start)) / 60);
    if minutes > public.punctuality_grace_minutes() then
      insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id, flag_date)
      values (new.user_id, 'late_clock_in', case when minutes > 60 then 'high' else 'medium' end,
              format('Clocked in %s late at %s (shift starts %s)',
                     public.minutes_label(minutes), shift.name, to_char(shift.shift_start, 'HH24:MI')),
              jsonb_build_object('attendance_id', new.id, 'minutes', minutes),
              shift.id, new.attendance_date);
    end if;
  elsif new.type = 'closing' then
    minutes := floor(extract(epoch from (new.attendance_date + shift.shift_end) - at_local) / 60);
    if minutes > public.punctuality_grace_minutes() then
      insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id, flag_date)
      values (new.user_id, 'early_clock_out', case when minutes > 60 then 'high' else 'medium' end,
              format('Clocked out %s early at %s (shift ends %s)',
                     public.minutes_label(minutes), shift.name, to_char(shift.shift_end, 'HH24:MI')),
              jsonb_build_object('attendance_id', new.id, 'minutes', minutes),
              shift.id, new.attendance_date);
    end if;
  end if;
  return null;
end;
$$;


--
-- Name: attendance_push_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_push_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me record;
begin
  if auth.uid() is null or new.type::text <> 'opening' then
    return new;
  end if;
  select p.role, p.push_exempt into me from public.profiles p where p.id = auth.uid();
  if public.is_field_role(me.role) and not coalesce(me.push_exempt, false)
     and not public.has_live_push(auth.uid()) then
    raise exception 'Turn on Xtend notifications before clocking in';
  end if;
  return new;
end;
$$;


--
-- Name: attendance_timing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_timing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  judged jsonb;
begin
  if new.user_id is null then
    return new;
  end if;
  judged := public.clock_timing(new.user_id, new.client_captured_at, new.device_info, now());
  new.time_verdict := judged->>'verdict';
  new.time_detail := judged - 'verdict';
  return new;
end;
$$;


--
-- Name: attendance_timing_flag(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attendance_timing_flag() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  what text := case when new.type::text = 'opening' then 'clock-in' else 'clock-out' end;
  d jsonb := coalesce(new.time_detail, '{}'::jsonb);
  off integer := coalesce((d->>'offset_s')::integer, 0);
begin
  if new.time_verdict = 'backdated' then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
    values (new.user_id, 'backdated_clock', 'high',
      format('The %s says it was taken at %s, offline, but the phone was in touch with Xtend at %s, after that. The time was changed on the phone',
             what, public.lagos_hm((d->>'taken_at')::timestamptz), public.lagos_hm((d->>'contact_at')::timestamptz)),
      d || jsonb_build_object('attendance_id', new.id), new.outlet_id);
  elsif new.time_verdict = 'phone_clock_wrong' then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
    values (new.user_id, 'phone_clock_wrong', 'medium',
      format('The phone''s clock was %s minutes %s at this %s. Phones set their own time; someone changed it',
             abs(off) / 60, case when off > 0 then 'ahead' else 'behind' end, what),
      d || jsonb_build_object('attendance_id', new.id), new.outlet_id);
  elsif new.time_verdict = 'network_was_available' then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
    values (new.user_id, 'late_sync_with_network', 'low',
      format('The %s was taken offline at %s and only sent at %s, but the phone had network at %s',
             what, public.lagos_hm((d->>'taken_at')::timestamptz), public.lagos_hm(new.created_at),
             public.lagos_hm((d->>'contact_at')::timestamptz)),
      d || jsonb_build_object('attendance_id', new.id), new.outlet_id);
  end if;
  return null;
end;
$$;


--
-- Name: audit_context_columns(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_context_columns(p jsonb) RETURNS TABLE(ip text, user_agent text, device jsonb, lat double precision, lng double precision, accuracy_m double precision, location_source text, place text, country text, vpn boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  la double precision;
  ln double precision;
  where_name text;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    return query select null::text, null::text, null::jsonb, null::float8, null::float8, null::float8,
                        null::text, null::text, null::text, null::boolean;
    return;
  end if;
  if jsonb_typeof(p->'lat') = 'number' and jsonb_typeof(p->'lng') = 'number'
     and abs((p->>'lat')::float8) <= 90 and abs((p->>'lng')::float8) <= 180 then
    la := (p->>'lat')::float8;
    ln := (p->>'lng')::float8;
    -- The store or known place the action was done in, if any.
    select o.name into where_name from public.outlets o where o.id = public.outlet_containing(la, ln);
    if where_name is null then
      select k.name into where_name from public.known_place_at(la, ln) k where k.source <> 'clock_in';
    end if;
  end if;
  return query select
    left(nullif(p->>'ip', ''), 64),
    left(nullif(p->>'user_agent', ''), 500),
    case when jsonb_typeof(p->'device') = 'object' then p->'device' end,
    la, ln,
    case when la is not null and jsonb_typeof(p->'accuracy_m') = 'number' and (p->>'accuracy_m')::float8 >= 0
         then (p->>'accuracy_m')::float8 end,
    case when la is not null and p->>'location_source' in ('browser', 'ip') then p->>'location_source' end,
    left(where_name, 200),
    left(nullif(p->>'country', ''), 8),
    case when jsonb_typeof(p->'vpn') = 'boolean' then (p->>'vpn')::boolean end;
end;
$$;


--
-- Name: audit_fill_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_fill_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c record;
  ctx jsonb;
begin
  if new.meta ? '_context' then
    ctx := new.meta->'_context';
  elsif new.ip is null and new.user_agent is null then
    begin
      ctx := convert_from(decode(
               nullif(current_setting('request.headers', true), '')::jsonb->>'x-xt-audit', 'base64'), 'utf8')::jsonb;
    exception when others then
      ctx := null;
    end;
  end if;
  if ctx is not null then
    select * into c from public.audit_context_columns(ctx);
    new.ip := coalesce(new.ip, c.ip);
    new.user_agent := coalesce(new.user_agent, c.user_agent);
    new.device := coalesce(new.device, c.device);
    new.lat := coalesce(new.lat, c.lat);
    new.lng := coalesce(new.lng, c.lng);
    new.accuracy_m := coalesce(new.accuracy_m, c.accuracy_m);
    new.location_source := coalesce(new.location_source, c.location_source);
    new.place := coalesce(new.place, c.place);
    new.country := coalesce(new.country, c.country);
    new.vpn := coalesce(new.vpn, c.vpn);
  end if;
  new.meta := coalesce(new.meta, '{}'::jsonb) - '_context';
  return new;
end;
$$;


