      or (public.supervises_user(target)
          and exists (select 1 from public.profiles p
                      where p.id = target and public.is_field_role(p.role)));
$$;


--
-- Name: can_count_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_count_stock() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.person_counts_stock(auth.uid());
$$;


--
-- Name: can_create_staff(public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_create_staff(p_role public.user_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_admin()
      or (public.current_user_role() = 'supervisor'::user_role
          and public.is_field_role(p_role));
$$;


--
-- Name: can_edit_staff(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_edit_staff(target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_admin() or public.supervises_user(target);
$$;


--
-- Name: can_file_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_file_report() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select role in ('marketer'::user_role, 'admin'::user_role)
     from public.profiles where id = auth.uid()),
    false);
$$;


--
-- Name: can_see_count_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_count_request(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_admin()
      or public.owns_count_request(p_id)
      or exists (select 1 from public.count_request_targets t
                 where t.request_id = p_id
                   and (t.user_id = auth.uid() or public.supervises_user(t.user_id)));
$$;


--
-- Name: can_send_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_send_notifications() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select role in ('admin'::user_role, 'supervisor'::user_role)
     from public.profiles where id = auth.uid()),
    false);
$$;


--
-- Name: can_visit_stores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_visit_stores() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select case p.role
      when 'marketer'::user_role then true
      when 'admin'::user_role then true
      when 'merchandiser'::user_role then
        (select count(*) from public.outlets_for_user(p.id)) > 1
      else false
    end
    from public.profiles p where p.id = auth.uid()
  ), false);
$$;


--
-- Name: cancel_scheduled_notification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_scheduled_notification(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s record;
begin
  select * into s from public.scheduled_notifications where id = p_id;
  if s.id is null then raise exception 'No such scheduled notification'; end if;
  if not (public.is_admin() or (s.created_by = auth.uid() and public.can_send_notifications())) then
    raise exception 'That is not yours to cancel';
  end if;
  if s.status <> 'scheduled' then raise exception 'It has already gone or been cancelled'; end if;
  update public.scheduled_notifications
  set status = 'cancelled', cancelled_by = auth.uid()
  where id = p_id and status = 'scheduled';
end;
$$;


--
-- Name: check_excuse(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_excuse(p_user uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result jsonb;
begin
  if not (public.is_admin() or public.supervises_user(p_user)) then
    raise exception 'You can only check your own team';
  end if;
  if p_to <= p_from or p_to - p_from > interval '72 hours' then
    raise exception 'Pick a time window of up to 3 days';
  end if;

  select jsonb_build_object(
    'contacts', coalesce((
      select jsonb_agg(c order by c.at) from (
        select b.received_at as at, 'app_' || b.reason as what, b.battery_pct, b.charging,
               b.connection, b.outbox_count, b.lat, b.lng,
               extract(epoch from (b.device_time - b.received_at))::integer as clock_off_s
        from public.device_beacons b
        where b.user_id = p_user and b.received_at between p_from and p_to
        union all
        select l.created_at, 'location', null, null, null, null, l.lat, l.lng, null
        from public.location_pings l
        where l.user_id = p_user and l.created_at between p_from and p_to and not l.offline
        union all
        select a.created_at, case when a.type::text = 'opening' then 'clock_in' else 'clock_out' end,
               null, null, null, null, a.lat, a.lng, null
        from public.attendance a
        where a.user_id = p_user and a.created_at between p_from and p_to
        union all
        select v.created_at, 'store_visit', null, null, null, null, v.arrived_lat, v.arrived_lng, null
        from public.store_visits v
        where v.user_id = p_user and v.created_at between p_from and p_to
        union all
        select pc.delivered_at, 'push_delivered', null, null, null, null, null, null, null
        from public.phone_checks pc
        where pc.user_id = p_user and pc.delivered_at between p_from and p_to
        order by 1
        limit 300
      ) c), '[]'::jsonb),
    'offline_positions', coalesce((
      select jsonb_agg(jsonb_build_object('at', l.created_at, 'received_at', l.received_at,
                                          'lat', l.lat, 'lng', l.lng) order by l.created_at)
      from public.location_pings l
      where l.user_id = p_user and l.offline and l.created_at between p_from and p_to), '[]'::jsonb),
    'offline_records', coalesce((
      select jsonb_agg(jsonb_build_object(
        'what', case when a.type::text = 'opening' then 'clock_in' else 'clock_out' end,
        'taken_at', coalesce((a.time_detail->>'taken_at')::timestamptz, a.client_captured_at),
        'sent_at', a.created_at, 'verdict', a.time_verdict, 'lat', a.lat, 'lng', a.lng)
        order by a.client_captured_at)
      from public.attendance a
      where a.user_id = p_user
        and coalesce((a.time_detail->>'taken_at')::timestamptz, a.client_captured_at) between p_from and p_to
        and a.created_at > coalesce((a.time_detail->>'taken_at')::timestamptz, a.client_captured_at)
                           + interval '2 minutes'), '[]'::jsonb),
    'before', (
      select to_jsonb(x) from (
        select b.received_at as at, b.battery_pct, b.charging, b.lat, b.lng
        from public.device_beacons b
        where b.user_id = p_user and b.received_at < p_from and b.received_at > p_from - interval '12 hours'
        order by b.received_at desc limit 1) x),
    'after', (
      select to_jsonb(x) from (
        select b.received_at as at, b.battery_pct, b.charging, b.lat, b.lng
        from public.device_beacons b
        where b.user_id = p_user and b.received_at > p_to and b.received_at < p_to + interval '12 hours'
        order by b.received_at limit 1) x),
    'place_before', (
      select to_jsonb(x) from (
        select t.at, t.lat, t.lng from (
          select l.created_at as at, l.lat, l.lng from public.location_pings l
          where l.user_id = p_user and l.created_at < p_from and l.created_at > p_from - interval '12 hours'
          union all
          select b.received_at, b.lat, b.lng from public.device_beacons b
          where b.user_id = p_user and b.lat is not null
            and b.received_at < p_from and b.received_at > p_from - interval '12 hours'
        ) t order by t.at desc limit 1) x),
    'place_after', (
      select to_jsonb(x) from (
        select t.at, t.lat, t.lng from (
          select l.created_at as at, l.lat, l.lng from public.location_pings l
          where l.user_id = p_user and l.created_at > p_to and l.created_at < p_to + interval '12 hours'
          union all
          select b.received_at, b.lat, b.lng from public.device_beacons b
          where b.user_id = p_user and b.lat is not null
            and b.received_at > p_to and b.received_at < p_to + interval '12 hours'
        ) t order by t.at limit 1) x),
    'phone_checks', coalesce((
      select jsonb_agg(jsonb_build_object('sent_at', pc.created_at, 'delivered_at', pc.delivered_at,
                                          'opened_at', pc.opened_at, 'devices', pc.devices)
                       order by pc.created_at)
      from public.phone_checks pc
      where pc.user_id = p_user and pc.created_at between p_from and p_to), '[]'::jsonb),
    'has_push', exists (select 1 from public.push_subscriptions s
                        where s.user_id = p_user and s.is_active),
    'ever_reported', exists (select 1 from public.device_beacons b where b.user_id = p_user)
  ) into result;
  return result;
end;
$$;


--
-- Name: check_excuse_more(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_excuse_more(p_user uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result jsonb;
begin
  if not (public.is_admin() or public.supervises_user(p_user)) then
    raise exception 'You can only check your own team';
  end if;
  if p_to <= p_from or p_to - p_from > interval '72 hours' then
    raise exception 'Pick a time window of up to 3 days';
  end if;

  with stores as (
    select o.id, o.name, o.lat, o.lng, o.geofence_radius_m as radius_m
    from public.outlets o
    where o.id in (select outlet_id from public.outlets_for_user(p_user)) and o.lat is not null
  ),
  positions as (
    select l.created_at as at, l.lat, l.lng, l.accuracy_m,
           case when l.offline then 'offline' else 'tracking' end as source
    from public.location_pings l
    where l.user_id = p_user and l.created_at between p_from and p_to
    union all
    select b.received_at, b.lat, b.lng, b.accuracy_m, 'app'
    from public.device_beacons b
    where b.user_id = p_user and b.received_at between p_from and p_to and b.lat is not null
    union all
    select a.created_at, a.lat, a.lng, a.accuracy_m, case when a.type::text = 'opening' then 'clock_in' else 'clock_out' end
    from public.attendance a
    where a.user_id = p_user and a.created_at between p_from and p_to
  ),
  placed as (
    select p.*, s.name as store, s.radius_m,
           public.distance_metres(p.lat, p.lng, s.lat, s.lng) as store_m
    from positions p
    left join lateral (
      select st.name, st.radius_m, st.lat, st.lng from stores st
      order by public.distance_metres(p.lat, p.lng, st.lat, st.lng) limit 1
    ) s on true
  )
  select jsonb_build_object(
    'stores', coalesce((select jsonb_agg(jsonb_build_object('name', name, 'radius_m', radius_m)) from stores), '[]'::jsonb),
    'positions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'at', at, 'lat', lat, 'lng', lng, 'accuracy_m', round(accuracy_m::numeric, 1), 'source', source,
        'store', store, 'store_m', round(store_m::numeric), 'radius_m', radius_m) order by at)
      from (select * from placed order by at limit 500) x), '[]'::jsonb),
    'location_problems', coalesce((
      select jsonb_agg(jsonb_build_object('at', a.created_at, 'kind', a.alert_type::text,
                                          'distance_m', round(a.distance_m::numeric)) order by a.created_at)
      from public.location_alerts a
      where a.user_id = p_user and a.created_at between p_from and p_to), '[]'::jsonb),
    'photos_refused', coalesce((
      select jsonb_agg(jsonb_build_object('at', c.created_at, 'kind', c.kind, 'problem', c.problem,
                                          'message', c.message) order by c.created_at)
      from public.photo_checks c
      where c.user_id = p_user and c.verdict = 'reject' and c.created_at between p_from and p_to), '[]'::jsonb),
    'queued', (
      select jsonb_build_object('most', max(b.outbox_count), 'oldest', min(b.oldest_queued_at))
      from public.device_beacons b
      where b.user_id = p_user and b.received_at between p_from and p_to and b.outbox_count > 0),
    'clock', coalesce((
      select jsonb_agg(jsonb_build_object('at', a.created_at, 'type', a.type::text, 'status', a.status::text,
                                          'distance_m', round(a.distance_m::numeric)) order by a.created_at)
      from public.attendance a
      where a.user_id = p_user and a.created_at between p_from and p_to), '[]'::jsonb),
    'visits', coalesce((
      select jsonb_agg(jsonb_build_object('at', v.created_at, 'status', v.arrived_status::text) order by v.created_at)
      from public.store_visits v
      where v.user_id = p_user and v.created_at between p_from and p_to), '[]'::jsonb)
  ) into result;
  return result;
end;
$$;


--
-- Name: check_store_count(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_store_count(p_outlet_id uuid, today date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  missing jsonb;
begin
  -- A correction later the same day replaces today's flags rather than adding more.
  delete from public.integrity_flags
  where user_id = auth.uid() and outlet_id = p_outlet_id and flag_date = today
    and kind like 'count_%' and reviewed_at is null;

  with cur as (
    select c.product_id, c.in_store, c.sold from public.store_counts c
    where c.user_id = auth.uid() and c.outlet_id = p_outlet_id and c.count_date = today
  ), prev as (
    select distinct on (c.product_id) c.product_id, c.in_store, c.sold
    from public.store_counts c
    where c.user_id = auth.uid() and c.outlet_id = p_outlet_id and c.count_date < today
    order by c.product_id, c.count_date desc
  )
  select jsonb_agg(jsonb_build_object(
           'product', pr.name, 'last_left', prev.in_store, 'sold', cur.sold,
           'expected_left', prev.in_store - cur.sold, 'left', cur.in_store,
           'missing', prev.in_store - cur.sold - cur.in_store))
    into missing
  from cur join prev using (product_id) join public.products pr on pr.id = cur.product_id
  -- Fewer units than last time minus what was sold: stock went somewhere.
  -- More is fine: that is a delivery.
  where prev.in_store - cur.sold - cur.in_store > greatest(2, 0.1 * prev.in_store);

  if missing is not null then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
    values (auth.uid(), 'count_units_missing', 'high',
            format('%s product(s) have fewer units left than the last count minus sales',
                   jsonb_array_length(missing)),
            jsonb_build_object('products', missing), p_outlet_id);
  end if;

  if (select count(*) from public.store_counts c
      where c.user_id = auth.uid() and c.outlet_id = p_outlet_id and c.count_date = today) >= 2
     and not exists (
       select 1 from public.store_counts cur
       where cur.user_id = auth.uid() and cur.outlet_id = p_outlet_id and cur.count_date = today
         and not exists (
           select 1 from public.store_counts prev
           where prev.user_id = cur.user_id and prev.outlet_id = cur.outlet_id
             and prev.product_id = cur.product_id and prev.in_store = cur.in_store
             and prev.sold = cur.sold
             and prev.count_date = (select max(p2.count_date) from public.store_counts p2
                                    where p2.user_id = cur.user_id and p2.outlet_id = cur.outlet_id
                                      and p2.count_date < today)))
  then
    insert into public.integrity_flags (user_id, kind, severity, summary, outlet_id)
    values (auth.uid(), 'count_identical', 'medium',
            'Every number is exactly the same as the previous count', p_outlet_id);
  end if;

  if (select count(*) from public.store_counts c
      where c.user_id = auth.uid() and c.outlet_id = p_outlet_id and c.count_date = today) >= 4
     and not exists (
       select 1 from public.store_counts c
       where c.user_id = auth.uid() and c.outlet_id = p_outlet_id and c.count_date = today
         and (c.in_store % 10 <> 0 or c.sold % 10 <> 0))
     and exists (
       select 1 from public.store_counts c
       where c.user_id = auth.uid() and c.outlet_id = p_outlet_id and c.count_date = today
         and (c.in_store > 0 or c.sold > 0))
  then
    insert into public.integrity_flags (user_id, kind, severity, summary, outlet_id)
    values (auth.uid(), 'count_round_numbers', 'low',
            'Every number in the count is a multiple of 10', p_outlet_id);
  end if;
end;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: scheduled_notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.scheduled_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_by uuid,
    title text NOT NULL,
    body text NOT NULL,
    url text,
    audience public.notification_audience NOT NULL,
    audience_detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    user_ids uuid[] NOT NULL,
    send_at timestamp with time zone NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    claimed_at timestamp with time zone,
    notification_id uuid,
    error text,
    cancelled_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    CONSTRAINT scheduled_notifications_body_check CHECK (((length(btrim(body)) >= 1) AND (length(btrim(body)) <= 400))),
    CONSTRAINT scheduled_notifications_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'sending'::text, 'sent'::text, 'cancelled'::text, 'failed'::text]))),
    CONSTRAINT scheduled_notifications_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 80))),
    CONSTRAINT scheduled_notifications_url_check CHECK (((url IS NULL) OR ((length(url) <= 300) AND (url ~ '^/([^/\\]|$)'::text))))
);


--
-- Name: claim_due_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_due_notifications(p_limit integer DEFAULT 20) RETURNS SETOF public.scheduled_notifications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.scheduled_notifications
  set status = 'failed', error = 'Interrupted while sending. Check the history before sending it again.'
  where status = 'sending' and claimed_at < now() - interval '15 minutes';

  return query
    update public.scheduled_notifications s
    set status = 'sending', claimed_at = now()
    where s.id in (
      select d.id from public.scheduled_notifications d
      where d.status = 'scheduled' and d.send_at <= now()
      order by d.send_at
      limit greatest(1, least(coalesce(p_limit, 20), 100))
      for update skip locked
    )
    returning s.*;
end;
$$;


--
-- Name: claim_flag_alerts(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_flag_alerts(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, user_id uuid, staff_name text, kind text, severity text, summary text, outlet_name text, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with due as (
    select f.id
    from public.integrity_flags f
    where f.notified_at is null
      and f.reviewed_at is null
      and f.severity in ('medium', 'high')
      and f.created_at > now() - interval '1 day'
    order by f.created_at
    limit greatest(1, least(p_limit, 200))
    for update skip locked
  ), told as (
    update public.integrity_flags f
    set notified_at = now()
    from due
    where f.id = due.id
    returning f.id, f.user_id, f.kind, f.severity, f.summary, f.outlet_id, f.created_at
  )
  select t.id, t.user_id, p.full_name, t.kind, t.severity, t.summary, o.name, t.created_at
  from told t
  join public.profiles p on p.id = t.user_id
  left join public.outlets o on o.id = t.outlet_id
  order by t.created_at;
$$;


--
-- Name: claim_scheduled_notification(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_scheduled_notification(p_id uuid) RETURNS SETOF public.scheduled_notifications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  s record;
begin
  select * into s from public.scheduled_notifications where id = p_id;
  if s.id is null then raise exception 'No such scheduled notification'; end if;
  if not (public.is_admin() or (s.created_by = auth.uid() and public.can_send_notifications())) then
    raise exception 'That is not yours to send';
  end if;
  return query
    update public.scheduled_notifications
    set status = 'sending', claimed_at = now()
    where id = p_id and status = 'scheduled'
    returning *;
  if not found then raise exception 'It has already gone or been cancelled'; end if;
end;
$$;


--
-- Name: claim_selfie_sweep(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_selfie_sweep(p_min_minutes integer DEFAULT 10) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.job_runs (job, last_run_at)
  values ('purge_selfies', '-infinity')
  on conflict (job) do nothing;

  update public.job_runs
  set last_run_at = now()
  where job = 'purge_selfies'
    and last_run_at < now() - make_interval(mins => greatest(1, p_min_minutes));

  return found;
end;
$$;


--
-- Name: clear_temp_password(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_temp_password() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.must_change_password is false and old.must_change_password is distinct from false then
    update public.staff_temp_passwords set password = null, set_at = now() where user_id = new.id;
  end if;
  return null;
end;
$$;


--
-- Name: clock_timing(uuid, timestamp with time zone, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_timing(p_user uuid, p_captured timestamp with time zone, p_device jsonb, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  sent timestamptz := public.safe_ts(p_device->>'sent_at');
  anchor uuid := public.safe_uuid(p_device->>'anchor_beacon');
  offset_s integer;
  taken timestamptz;
  anchor_at timestamptz;
  empty_at timestamptz;
  online_at timestamptz;
  last_before timestamptz;
  verdict text;
  detail jsonb := '{}'::jsonb;
begin
  -- How far the phone's clock was from the server's when it sent this.
  if sent is not null then
    offset_s := extract(epoch from (sent - p_now))::integer;
  end if;
  -- When it was really taken, on the server's clock.
  taken := p_captured - make_interval(secs => coalesce(offset_s, 0));
  detail := jsonb_build_object('offset_s', offset_s, 'taken_at', taken,
                               'lag_s', extract(epoch from (p_now - taken))::integer);

  if p_now - taken <= interval '2 minutes' then
    verdict := 'live';
  else
    -- The phone was in touch after the moment it claims: impossible.
    select b.received_at into anchor_at
    from public.device_beacons b where b.id = anchor and b.user_id = p_user;
    if anchor_at > taken + interval '2 minutes' then
      verdict := 'backdated';
      detail := detail || jsonb_build_object('contact_at', anchor_at, 'how', 'anchor');
    end if;

    -- Or it reported, well after that moment, that nothing was waiting.
    if verdict is null then
      select b.received_at into empty_at
      from public.device_beacons b
      where b.user_id = p_user and b.outbox_count = 0
        and b.received_at > taken + interval '10 minutes'
        and b.received_at < p_now - interval '30 seconds'
      order by b.received_at limit 1;
      if empty_at is not null then
        verdict := 'backdated';
        detail := detail || jsonb_build_object('contact_at', empty_at, 'how', 'nothing_waiting');
      end if;
    end if;

    -- The phone had network long before it sent this.
    if verdict is null then
      select min(t) into online_at from (
        select b.received_at as t from public.device_beacons b
        where b.user_id = p_user and b.received_at > taken + interval '10 minutes'
          and b.received_at < p_now - interval '10 minutes'
        union all
        select l.created_at from public.location_pings l
        where l.user_id = p_user and not l.offline and l.created_at > taken + interval '10 minutes'
          and l.created_at < p_now - interval '10 minutes'
      ) x;
      if online_at is not null then
        verdict := 'network_was_available';
        detail := detail || jsonb_build_object('contact_at', online_at);
      end if;
    end if;

    if verdict is null then
      select max(t) into last_before from (
        select b.received_at as t from public.device_beacons b
        where b.user_id = p_user and b.received_at <= taken + interval '2 minutes'
          and b.received_at > taken - interval '1 day'
        union all
        select l.created_at from public.location_pings l
        where l.user_id = p_user and not l.offline and l.created_at <= taken + interval '2 minutes'
          and l.created_at > taken - interval '1 day'
      ) x;
      verdict := case when last_before is not null then 'offline_confirmed' else 'offline_unproven' end;
      detail := detail || jsonb_build_object('last_contact_at', last_before);
    end if;
  end if;

  if abs(coalesce(offset_s, 0)) > 300 and verdict <> 'backdated' then
    verdict := 'phone_clock_wrong';
  end if;
  return detail || jsonb_build_object('verdict', verdict);
end;
$$;


--
-- Name: close_abandoned_visits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_abandoned_visits() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n integer;
begin
  update public.store_visits
  set status = 'abandoned'
  where status = 'open' and visit_date < public.business_date();
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: close_count_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_count_request(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.count_requests
  set closed_at = now()
  where id = p_request_id
    and closed_at is null
    and (requested_by = auth.uid() or public.is_admin());
  if not found then
    raise exception 'That request is already closed, or it is not yours to close';
  end if;
end;
$$;


--
-- Name: counted_product_names(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.counted_product_names() RETURNS TABLE(name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.name from public.products p
  where public.can_count_stock() or public.is_admin()
  order by p.name
  limit 2000;
$$;


--
-- Name: coverage_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coverage_today() RETURNS TABLE(user_id uuid, full_name text, outlet_name text, ping_count integer, coverage_pct integer, last_ping_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id,
    p.full_name,
    o.name,
    (public.tracking_coverage(p.id, public.business_date()) ->> 'ping_count')::int,
    (public.tracking_coverage(p.id, public.business_date()) ->> 'coverage_pct')::int,
    (public.tracking_coverage(p.id, public.business_date()) ->> 'last_ping_at')::timestamptz
  from public.profiles p
  left join public.outlets o on o.id = p.outlet_id
  where p.is_active
    and public.is_field_role(p.role)
    and (public.is_admin() or public.supervises_user(p.id))
    and exists (
      select 1 from public.attendance a
      where a.user_id = p.id
        and a.attendance_date = public.business_date()
        and a.type = 'opening'
    )
  order by p.full_name;
$$;


--
-- Name: current_user_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_role() RETURNS public.user_role
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select role from public.profiles where id = auth.uid();
$$;


--
-- Name: dismiss_place_due(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_place_due(p_due uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare who uuid;
begin
  select user_id into who from public.place_naming_due where id = p_due;
  if who is null then raise exception 'That does not exist'; end if;
  if not (public.is_admin() or public.supervises_user(who)) then
    raise exception 'Only an admin or their supervisor can do that';
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'Say why';
  end if;
  update public.place_naming_due
  set dismissed_at = now(), dismissed_by = auth.uid(), dismiss_reason = btrim(p_reason)
  where id = p_due and named_at is null and dismissed_at is null;
  if not found then raise exception 'It was already named or dismissed'; end if;
end;
$$;


--
-- Name: distance_metres(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distance_metres(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select 6371000 * 2 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) *
    power(sin(radians(lng2 - lng1) / 2), 2)
  ));
$$;


--
-- Name: end_store_visit(uuid, double precision, double precision, double precision, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_store_visit(p_visit_id uuid, p_lat double precision, p_lng double precision, p_accuracy_m double precision, p_place_name text DEFAULT NULL::text, p_address text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v record;
  new_distance double precision;
  new_status attendance_status;
begin
  select * into v from public.store_visits
  where id = p_visit_id and user_id = auth.uid();

  if v is null then
    raise exception 'That visit is not yours or does not exist';
  end if;
  if v.status <> 'open' then
    raise exception 'That visit is already closed';
  end if;

  if v.outlet_lat is null then
    new_distance := null;
    new_status := case when p_accuracy_m > 100 then 'flagged'::attendance_status else null end;
  else
    new_distance := public.distance_metres(p_lat, p_lng, v.outlet_lat, v.outlet_lng);
    new_status := case
      when p_accuracy_m > 100 then 'flagged'::attendance_status
      when new_distance <= coalesce(v.outlet_radius_m, 150) then 'on_site'::attendance_status
      else 'off_site'::attendance_status
    end;
  end if;

  update public.store_visits
  set status              = 'closed',
      departed_at         = now(),
      departed_lat        = p_lat,
      departed_lng        = p_lng,
      departed_accuracy_m = p_accuracy_m,
      departed_distance_m = new_distance,
      departed_status     = new_status,
      departed_place_name = p_place_name,
      departed_address    = p_address
  where id = p_visit_id;

  return jsonb_build_object(
    'id', p_visit_id,
    'departed_at', now(),
    'distance_m', new_distance,
    'status', new_status,
    'minutes', (extract(epoch from (now() - v.arrived_at)) / 60)::int
  );
end;
$$;


--
-- Name: expired_selfie_paths(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expired_selfie_paths(p_hours integer DEFAULT 24) RETURNS TABLE(path text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with cutoff as (select now() - make_interval(hours => greatest(1, p_hours)) as at)
  select unnest(array_remove(array[a.selfie_path, a.thumb_path], null))
  from public.attendance a, cutoff c
  where a.created_at < c.at and (a.selfie_path is not null or a.thumb_path is not null)
  union
  select unnest(array_remove(array[v.selfie_path, v.thumb_path], null))
  from public.store_visits v, cutoff c
  where v.created_at < c.at and (v.selfie_path is not null or v.thumb_path is not null);
$$;


--
-- Name: finish_onboarding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_onboarding() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;
  update public.profiles set onboarded_at = coalesce(onboarded_at, now()) where id = auth.uid();
end;
$$;


--
-- Name: flag_location(uuid, double precision, double precision, double precision, timestamp with time zone, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flag_location(p_user uuid, p_lat double precision, p_lng double precision, p_accuracy double precision, p_at timestamp with time zone, p_source text, p_check_repeat boolean, p_outlet uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  prev record;
  km double precision;
  hours double precision;
begin
  -- Real GPS wobbles by a few metres every time. The exact same point to
  -- the tenth of a metre, on another day, is what a fake-location app gives.
  if p_check_repeat and exists (
    select 1 from public.attendance a
    where a.user_id = p_user
      and a.attendance_date <> public.business_date()
      and round(a.lat::numeric, 6) = round(p_lat::numeric, 6)
      and round(a.lng::numeric, 6) = round(p_lng::numeric, 6)
  ) then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
    values (p_user, 'repeated_exact_location', 'high',
            'Clocked in at exactly the same GPS point as on an earlier day',
            jsonb_build_object('lat', p_lat, 'lng', p_lng, 'source', p_source), p_outlet);
  end if;

  -- Phones indoors report 5 to 50 m. Under 2 m, every time, is a fake.
  if p_check_repeat and p_accuracy < 2 then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
    values (p_user, 'perfect_accuracy', 'medium',
            format('GPS accuracy reported as %s m, which phones do not achieve indoors',
                   round(p_accuracy::numeric, 1)),
            jsonb_build_object('accuracy_m', p_accuracy, 'source', p_source), p_outlet);
  end if;

  -- The previous known position today, from a clock event or a heartbeat.
  select x.lat, x.lng, x.at into prev
  from (
    select a.lat, a.lng, a.created_at as at from public.attendance a
    where a.user_id = p_user and a.created_at < p_at and a.created_at > p_at - interval '6 hours'
    union all
    select l.lat, l.lng, l.created_at from public.location_pings l
    where l.user_id = p_user and l.created_at < p_at and l.created_at > p_at - interval '6 hours'
  ) x
  order by x.at desc
  limit 1;

  if prev.at is not null then
    km := public.distance_metres(prev.lat, prev.lng, p_lat, p_lng) / 1000.0;
    hours := greatest(extract(epoch from (p_at - prev.at)) / 3600.0, 1.0 / 3600);
    -- Faster than 150 km/h over more than 3 km, at most once an hour.
    if km > 3 and km / hours > 150 and not exists (
      select 1 from public.integrity_flags f
      where f.user_id = p_user and f.kind = 'impossible_journey'
        and f.created_at > now() - interval '1 hour'
    ) then
      insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
      values (p_user, 'impossible_journey', 'high',
              format('Moved %s km in %s minutes (%s km/h)', round(km::numeric, 1),
                     round((hours * 60)::numeric), round((km / hours)::numeric)),
              jsonb_build_object('km', round(km::numeric, 2), 'minutes', round((hours * 60)::numeric, 1),
                                 'source', p_source), p_outlet);
    end if;
  end if;
end;
$$;


--
-- Name: flag_own_integrity(text, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flag_own_integrity(p_kind text, p_severity text, p_summary text, p_detail jsonb DEFAULT '{}'::jsonb, p_outlet uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'Not authenticated';
  end if;

  if p_kind not in ('vpn_suspected', 'ip_location_mismatch',
                    'timezone_mismatch', 'gps_mock_fingerprint',
                    'mock_location_confirmed', 'device_integrity_failed') then
    raise exception 'flag_own_integrity does not accept kind %', p_kind;
  end if;

  if p_severity not in ('low', 'medium', 'high') then
    p_severity := 'medium';
  end if;

  if exists (
    select 1 from public.integrity_flags f
    where f.user_id = uid
      and f.kind = p_kind
      and f.created_at > now() - interval '1 hour'
  ) then
    return;
  end if;

  insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id)
  values (uid, p_kind, p_severity, left(p_summary, 300), coalesce(p_detail, '{}'::jsonb), p_outlet);
end;
$$;


--
-- Name: forget_expired_selfies(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forget_expired_selfies(p_hours integer DEFAULT 24) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cutoff timestamptz := now() - make_interval(hours => greatest(1, p_hours));
  a integer;
  v integer;
begin
  update public.attendance
  set selfie_path = null, thumb_path = null
  where created_at < cutoff and (selfie_path is not null or thumb_path is not null);
  get diagnostics a = row_count;

  update public.store_visits
  set selfie_path = null, thumb_path = null
  where created_at < cutoff and (selfie_path is not null or thumb_path is not null);
  get diagnostics v = row_count;

  return a + v;
end;
$$;


--
-- Name: has_live_push(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_live_push(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  select exists (
    select 1 from public.push_subscriptions s
    where s.user_id = p_user and s.is_active
      and (s.endpoint ~ '^https://(fcm\.googleapis\.com|android\.googleapis\.com|updates\.push\.services\.mozilla\.com|web\.push\.apple\.com|[a-z0-9.-]+\.notify\.windows\.com)/'
           or s.endpoint ~ '^native-(fcm|apns):[A-Za-z0-9_:-]{20,}$')
  );
$_$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select role from public.profiles where id = auth.uid()) = 'admin', false);
$$;


--
-- Name: is_field_role(public.user_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_field_role(r public.user_role) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select r in ('merchandiser'::user_role, 'marketer'::user_role);
$$;


--
-- Name: is_month_end_window(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_month_end_window(d date DEFAULT public.business_date()) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select d > ((date_trunc('month', d) + interval '1 month')::date - public.month_end_count_days() - 1)
$$;


--
-- Name: issue_tracking_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_tracking_token(p_platform text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  token text;
  expires timestamptz;
begin
  if me is null then
    raise exception 'Sign in first';
  end if;
  if not exists (select 1 from public.profiles
                 where id = me and is_active and role in ('merchandiser', 'marketer')) then
    raise exception 'Only field staff use this';
  end if;
  if p_platform not in ('android', 'ios') then
    raise exception 'Unknown platform';
  end if;

  update public.tracking_tokens set revoked_at = now()
  where user_id = me and platform = p_platform and revoked_at is null;

  token := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  -- Long enough for the longest shift, never into the next one.
  expires := now() + interval '18 hours';
  insert into public.tracking_tokens (user_id, token_hash, platform, expires_at)
  values (me, encode(sha256(convert_to(token, 'utf8')), 'hex'), p_platform, expires);
  return jsonb_build_object('token', token, 'expires_at', expires);
end;
$$;


--
-- Name: known_place_at(double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.known_place_at(p_lat double precision, p_lng double precision) RETURNS TABLE(id uuid, name text, address text, source text, verified boolean, distance_m double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select k.id, k.name, k.address, k.source, k.verified,
         public.distance_metres(p_lat, p_lng, k.lat, k.lng) as distance_m
  from public.known_places k
  where k.lat between p_lat - 0.01 and p_lat + 0.01
    and k.lng between p_lng - 0.01 and p_lng + 0.01
    and public.distance_metres(p_lat, p_lng, k.lat, k.lng) <= k.radius_m
  order by k.verified desc, public.distance_metres(p_lat, p_lng, k.lat, k.lng)
  limit 1;
$$;


--
-- Name: lagos_hm(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lagos_hm(t timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select to_char(t at time zone 'Africa/Lagos', 'HH24:MI');
$$;


--
-- Name: learn_place(double precision, double precision, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learn_place(p_lat double precision, p_lng double precision, p_name text, p_address text, p_source text, p_photo_path text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  clean text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  found uuid;
  clash record;
begin
  if me is null then
    raise exception 'Sign in first';
  end if;
  if p_source not in ('google', 'osm', 'staff') then
    raise exception 'Unknown place source';
  end if;
  if length(clean) < 2 or length(clean) > 120 then
    raise exception 'A place name needs 2 to 120 characters';
  end if;

  if public.outlet_containing(p_lat, p_lng) is not null then
    return null;
  end if;

  select k.id into found from public.known_place_at(p_lat, p_lng) k;
  if found is not null then
    update public.known_places
    set times_seen = times_seen + 1, last_seen_at = now(),
        visitors = case when me = any(visitors) then visitors else visitors || me end
    where id = found;
    return found;
  end if;

  if p_source = 'staff' then
    select x.name, x.km into clash from (
      select o.name, public.distance_metres(p_lat, p_lng, o.lat, o.lng) / 1000.0 as km
      from public.outlets o
      where o.is_active and public.names_overlap(o.name, clean)
      union all
      select k.name, public.distance_metres(p_lat, p_lng, k.lat, k.lng) / 1000.0
      from public.known_places k
      where k.verified and public.names_overlap(k.name, clean)
    ) x
    where x.km > 0.5
    order by x.km
    limit 1;
    if clash.name is not null then
      raise exception 'That name does not match where you are standing. Type the name on the sign here';
    end if;

    if p_photo_path is null or not public.photo_is_fresh('reports', p_photo_path, 30)
       or not exists (select 1 from public.photo_checks c
                      where c.path = p_photo_path and c.kind = 'storefront') then
      raise exception 'Take a photo of the shop front or sign';
    end if;
    if exists (select 1 from public.known_places k where k.photo_path = p_photo_path) then
      raise exception 'Take a new photo here';
    end if;

    if (select count(*) from public.known_places k
        where k.named_by = me and k.source = 'staff' and k.created_at > now() - interval '1 day') >= 10 then
      raise exception 'No more place names can be added today';
    end if;
  end if;

  insert into public.known_places (name, address, lat, lng, source, named_by, photo_path, visitors)
  values (clean, nullif(btrim(coalesce(p_address, '')), ''), p_lat, p_lng, p_source,
          case when p_source = 'staff' then me end,
          case when p_source = 'staff' then p_photo_path end,
          array[me])
  returning id into found;
  return found;
end;
$$;


--
-- Name: live_locations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.live_locations() RETURNS TABLE(user_id uuid, full_name text, phone text, outlet_name text, outlet_lat double precision, outlet_lng double precision, outlet_radius_m integer, clocked_in_at timestamp with time zone, clock_in_label text, clock_in_status public.attendance_status, last_ping_at timestamp with time zone, minutes_since_ping integer, last_lat double precision, last_lng double precision, last_place_name text, distance_from_outlet_m double precision, inside_geofence boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with visible as (
    select p.id, p.full_name, p.phone, o.name as outlet_name,
           o.lat as o_lat, o.lng as o_lng, o.geofence_radius_m
    from public.profiles p
    left join public.outlets o on o.id = p.outlet_id
    where p.is_active
      and public.is_field_role(p.role)
      and (public.is_admin() or public.supervises_user(p.id))
  ),
  opening as (
    select a.user_id, a.created_at, a.status, a.lat, a.lng,
           coalesce(
             nullif(trim(both ', ' from concat_ws(', ', a.place_name,
               nullif(a.address, a.place_name))), ''),
             a.address,
             round(a.lat::numeric, 5) || ', ' || round(a.lng::numeric, 5)
           ) as label
    from public.attendance a
    where a.attendance_date = public.business_date() and a.type = 'opening'
  ),
  closing as (
    select a.user_id from public.attendance a
    where a.attendance_date = public.business_date() and a.type = 'closing'
  ),
  latest_ping as (
    select distinct on (p.user_id)
      p.user_id, p.created_at, p.lat, p.lng, p.place_name
    from public.location_pings p
    where p.created_at >= (public.business_date()::timestamp at time zone 'Africa/Lagos')
    order by p.user_id, p.created_at desc
  )
  select
    v.id,
    v.full_name,
    v.phone,
    v.outlet_name,
    v.o_lat,
    v.o_lng,
    v.geofence_radius_m,
    op.created_at,
    op.label,
    op.status,
    lp.created_at,
    case when lp.created_at is null then null
         else (extract(epoch from (now() - lp.created_at)) / 60)::int end,
    coalesce(lp.lat, op.lat),
    coalesce(lp.lng, op.lng),
    lp.place_name,
    case
      when v.o_lat is null then null
      else public.distance_metres(coalesce(lp.lat, op.lat), coalesce(lp.lng, op.lng), v.o_lat, v.o_lng)
    end,
    case
      when v.o_lat is null then null
      else public.distance_metres(coalesce(lp.lat, op.lat), coalesce(lp.lng, op.lng), v.o_lat, v.o_lng)
             <= v.geofence_radius_m
    end
  from visible v
  join opening op on op.user_id = v.id
  left join latest_ping lp on lp.user_id = v.id
  where not exists (select 1 from closing c where c.user_id = v.id)
  order by v.full_name;
$$;


--
-- Name: log_location_block(text, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_location_block(p_reason text, p_accuracy_m double precision DEFAULT NULL::double precision) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  new_id uuid;
  kind alert_type;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  kind := case when p_reason = 'low_accuracy' then 'low_accuracy'::alert_type
               else 'permission_denied'::alert_type end;

  -- One row per user per reason per 15 minutes. A retry loop must not
  -- flood the admin queue.
  select id into new_id
  from public.location_alerts
  where user_id = auth.uid()
    and alert_type = kind
    and created_at > now() - interval '15 minutes'
  limit 1;

  if new_id is not null then
    return new_id;
  end if;

  insert into public.location_alerts (user_id, alert_type, distance_m)
  values (auth.uid(), kind, p_accuracy_m)
  returning id into new_id;

  return new_id;
end;
$$;


--
-- Name: mark_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notifications_read() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  n integer;
begin
  update public.notification_deliveries
  set read_at = now()
  where user_id = auth.uid() and read_at is null and status = 'sent';
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: minutes_label(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.minutes_label(p_minutes integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_minutes < 60 then p_minutes || ' min'
    when p_minutes % 60 = 0 then (p_minutes / 60) || ' h'
    else (p_minutes / 60) || ' h ' || (p_minutes % 60) || ' min'
  end;
$$;


--
-- Name: month_end_count_days(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.month_end_count_days() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ select 3 $$;


--
-- Name: movement_trail(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movement_trail(p_user uuid, p_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  day_start timestamptz := (p_date::timestamp at time zone 'Africa/Lagos');
  day_end   timestamptz := ((p_date + 1)::timestamp at time zone 'Africa/Lagos');
  result jsonb;
begin
  if not (public.is_admin() or public.supervises_user(p_user)) then
    raise exception 'You can only follow your own team';
  end if;

  with points as (
    select a.created_at as at,
           case when a.type::text = 'opening' then 'clock_in' else 'clock_out' end as kind,
           a.lat, a.lng, a.accuracy_m, a.distance_m,
           coalesce(a.place_name, a.address) as place, a.outlet_id
    from public.attendance a
    where a.user_id = p_user and a.created_at >= day_start and a.created_at < day_end
    union all
    select l.created_at, case when l.offline then 'location_offline' else 'location' end,
           l.lat, l.lng, l.accuracy_m, l.distance_m, l.place_name, null
    from public.location_pings l
    where l.user_id = p_user and l.created_at >= day_start and l.created_at < day_end
    union all
    select v.arrived_at, 'visit_in', v.arrived_lat, v.arrived_lng, v.arrived_accuracy_m, null,
           o.name, v.outlet_id
    from public.store_visits v
    left join public.outlets o on o.id = v.outlet_id
    where v.user_id = p_user and v.arrived_at >= day_start and v.arrived_at < day_end
    union all
    select v.departed_at, 'visit_out', v.departed_lat, v.departed_lng, v.departed_accuracy_m, null,
           o.name, v.outlet_id
    from public.store_visits v
    left join public.outlets o on o.id = v.outlet_id
    where v.user_id = p_user and v.departed_at >= day_start and v.departed_at < day_end
      and v.departed_lat is not null
    union all
    select b.received_at, 'app', b.lat, b.lng, b.accuracy_m, null, null, null
    from public.device_beacons b
    where b.user_id = p_user and b.lat is not null
      and b.received_at >= day_start and b.received_at < day_end
  ),
  stores as (
    select o.id, o.name, o.lat, o.lng, o.geofence_radius_m as radius_m
    from public.outlets o
    where o.lat is not null and (
      o.id in (select f.outlet_id from public.outlets_for_user(p_user) f)
      or o.id in (select p.outlet_id from points p where p.outlet_id is not null)
    )
  )
  select jsonb_build_object(
    'person', (select jsonb_build_object('id', pr.id, 'name', pr.full_name, 'phone', pr.phone, 'role', pr.role)
               from public.profiles pr where pr.id = p_user),
    'date', p_date,
    'points', coalesce((select jsonb_agg(to_jsonb(p) order by p.at) from points p
                        where p.lat is not null and p.lng is not null), '[]'::jsonb),
    'stores', coalesce((select jsonb_agg(to_jsonb(s)) from stores s), '[]'::jsonb)
  ) into result;
  return result;
end;
$$;


--
-- Name: my_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_coverage() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.tracking_coverage(auth.uid(), public.business_date());
$$;


--
-- Name: my_day(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_day() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'date', public.business_date(),
    'can_file_report', public.can_file_report(),
    'profile', (
      select jsonb_build_object(
        'id', p.id, 'full_name', p.full_name, 'role', p.role,
        'must_change_password', p.must_change_password, 'is_active', p.is_active
      ) from public.profiles p where p.id = auth.uid()
    ),
    'outlet', (
      select jsonb_build_object(
        'id', o.id, 'name', o.name, 'address', o.address,
        'lat', o.lat, 'lng', o.lng, 'radius_m', o.geofence_radius_m,
        'shift_start', o.shift_start, 'shift_end', o.shift_end
      )
      from public.outlets o
      join public.profiles p on p.outlet_id = o.id
      where p.id = auth.uid()
    ),
    'opening', (
      select jsonb_build_object('id', a.id, 'at', a.created_at, 'status', a.status,
                                'distance_m', a.distance_m, 'address', a.address)
      from public.attendance a
      where a.user_id = auth.uid() and a.attendance_date = public.business_date()
        and a.type = 'opening'
    ),
    'closing', (
      select jsonb_build_object('id', a.id, 'at', a.created_at, 'status', a.status,
                                'distance_m', a.distance_m, 'address', a.address)
      from public.attendance a
      where a.user_id = auth.uid() and a.attendance_date = public.business_date()
        and a.type = 'closing'
    ),
    'report_filed', exists (
      select 1 from public.reports r
      where r.user_id = auth.uid() and r.report_date = public.business_date()
    )
  );
$$;


--
-- Name: my_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_notifications(p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, title text, body text, url text, sent_at timestamp with time zone, sender_name text, read_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select n.id, n.title, n.body, n.url, n.created_at, s.full_name, d.read_at
  from public.notification_deliveries d
  join public.notifications n on n.id = d.notification_id
  left join public.profiles s on s.id = n.sender_id
  where d.user_id = auth.uid() and d.status = 'sent'
  order by n.created_at desc
  limit greatest(1, least(coalesce(p_limit, 20), 100));
$$;


--
-- Name: my_open_count_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_open_count_request() RETURNS TABLE(id uuid, due_date date, note text, requested_by_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.id, r.due_date, r.note, p.full_name
  from public.count_requests r
  join public.count_request_targets t on t.request_id = r.id
  join public.profiles p on p.id = r.requested_by
  where t.user_id = auth.uid()
    and r.closed_at is null
    and r.due_date >= public.business_date()
  order by r.due_date, r.created_at
  limit 1;
$$;


--
-- Name: outlets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outlets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    address text,
    lat double precision,
    lng double precision,
    geofence_radius_m integer DEFAULT 150 NOT NULL,
    shift_start time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    shift_end time without time zone DEFAULT '18:00:00'::time without time zone NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT outlets_geofence_radius_m_check CHECK (((geofence_radius_m >= 25) AND (geofence_radius_m <= 2000))),
    CONSTRAINT outlets_location_whole CHECK (((lat IS NULL) = (lng IS NULL)))
);


--
-- Name: my_outlets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_outlets() RETURNS SETOF public.outlets
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.* from public.outlets o
  where o.id in (select outlet_id from public.outlets_for_user(auth.uid()))
  order by o.name;
$$;


--
-- Name: my_place_due(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_place_due() RETURNS TABLE(id uuid, lat double precision, lng double precision, source_kind text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select d.id, d.lat, d.lng, d.source_kind, d.created_at
  from public.place_naming_due d
  where d.user_id = auth.uid() and d.due_date = public.business_date()
    and d.named_at is null and d.dismissed_at is null
  order by d.created_at
  limit 1;
$$;


--
-- Name: profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    full_name text NOT NULL,
    phone text,
    role public.user_role DEFAULT 'merchandiser'::public.user_role NOT NULL,
    outlet_id uuid,
    avatar_path text,
    is_active boolean DEFAULT true NOT NULL,
    must_change_password boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    email text,
    supervisor_id uuid,
    push_exempt boolean DEFAULT false NOT NULL,
    onboarded_at timestamp with time zone,
    staff_role_id uuid
);


--
-- Name: my_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_staff() RETURNS SETOF public.profiles
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.* from public.profiles p
  where public.is_admin() or public.supervises_user(p.id) or p.id = auth.uid()
  order by p.full_name;
$$;


--
-- Name: store_visits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.store_visits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid DEFAULT auth.uid() NOT NULL,
    outlet_id uuid,
    visit_date date,
    status public.visit_status DEFAULT 'open'::public.visit_status NOT NULL,
    arrived_at timestamp with time zone,
    arrived_lat double precision NOT NULL,
    arrived_lng double precision NOT NULL,
    arrived_accuracy_m double precision NOT NULL,
    arrived_distance_m double precision,
    arrived_status public.attendance_status,
    arrived_place_name text,
    arrived_address text,
    selfie_path text,
    thumb_path text,
    departed_at timestamp with time zone,
    departed_lat double precision,
    departed_lng double precision,
    departed_accuracy_m double precision,
    departed_distance_m double precision,
    departed_status public.attendance_status,
    departed_place_name text,
    departed_address text,
    outlet_lat double precision,
    outlet_lng double precision,
    outlet_radius_m integer,
    device_info jsonb DEFAULT '{}'::jsonb NOT NULL,
    client_captured_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: store_visit_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.store_visit_detail WITH (security_invoker='true') AS
 SELECT v.id,
    v.user_id,
    p.full_name AS staff_name,
    p.phone AS staff_phone,
    v.outlet_id,
    o.name AS outlet_name,
    o.address AS outlet_address,
    v.visit_date,
    v.status,
    v.arrived_at,
    v.departed_at,
        CASE
            WHEN (v.departed_at IS NULL) THEN ((EXTRACT(epoch FROM (now() - v.arrived_at)) / (60)::numeric))::integer
            ELSE ((EXTRACT(epoch FROM (v.departed_at - v.arrived_at)) / (60)::numeric))::integer
        END AS minutes,
    v.arrived_status,
    v.departed_status,
    (round(v.arrived_distance_m))::integer AS arrived_distance_m,
    (round(v.departed_distance_m))::integer AS departed_distance_m,
    v.arrived_accuracy_m,
    v.arrived_lat,
    v.arrived_lng,
    v.outlet_radius_m,
    v.selfie_path,
    v.thumb_path,
    COALESCE(NULLIF(TRIM(BOTH ', '::text FROM concat_ws(', '::text, v.arrived_place_name, NULLIF(v.arrived_address, v.arrived_place_name))), ''::text), v.arrived_address, ((round((v.arrived_lat)::numeric, 5) || ', '::text) || round((v.arrived_lng)::numeric, 5))) AS arrived_label,
    v.arrived_place_name,
    v.arrived_address,
    COALESCE(
        CASE
            WHEN (v.arrived_status = 'on_site'::public.attendance_status) THEN o.name
            ELSE NULL::text
        END, NULLIF(v.arrived_place_name, ''::text), NULLIF(v.arrived_address, ''::text), o.name, 'Unnamed place'::text) AS store_label,
        CASE
            WHEN ((v.arrived_status = 'on_site'::public.attendance_status) AND (o.name IS NOT NULL)) THEN 'outlet'::text
            WHEN (COALESCE(NULLIF(v.arrived_place_name, ''::text), NULLIF(v.arrived_address, ''::text)) IS NOT NULL) THEN 'map'::text
            ELSE 'outlet'::text
        END AS store_label_source,
    v.departed_lat,
    v.departed_lng,
    v.departed_accuracy_m,
    COALESCE(NULLIF(TRIM(BOTH ', '::text FROM concat_ws(', '::text, v.departed_place_name, NULLIF(v.departed_address, v.departed_place_name))), ''::text), v.departed_address,
        CASE
            WHEN (v.departed_lat IS NOT NULL) THEN ((round((v.departed_lat)::numeric, 5) || ', '::text) || round((v.departed_lng)::numeric, 5))
            ELSE NULL::text
        END) AS departed_label,
    v.outlet_lat,
    v.outlet_lng
   FROM ((public.store_visits v
     JOIN public.profiles p ON ((p.id = v.user_id)))
     LEFT JOIN public.outlets o ON ((o.id = v.outlet_id)));


--
-- Name: my_store_visits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_store_visits() RETURNS SETOF public.store_visit_detail
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from public.store_visit_detail
  where user_id = auth.uid() and visit_date = public.business_date()
  order by arrived_at desc;
$$;


--
-- Name: name_place(uuid, text, double precision, double precision, double precision, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.name_place(p_due uuid, p_name text, p_lat double precision, p_lng double precision, p_accuracy_m double precision, p_storefront_path text, p_selfie_path text, p_evidence jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  sign_at record;
  selfie_at record;
  me uuid := auth.uid();
  due public.place_naming_due;
  clean text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  clash text;
  here record;
  place uuid;
begin
  select * into due from public.place_naming_due where id = p_due;
  if due.id is null or due.user_id <> me then
    raise exception 'There is no place for you to name';
  end if;
  if due.named_at is not null or due.dismissed_at is not null then
    return due.place_id;
  end if;

  if length(clean) < 2 or length(clean) > 120 then
    raise exception 'Type the name on the store sign';
  end if;
  if p_lat is null or p_lng is null or p_accuracy_m is null or p_accuracy_m > 100 then
    raise exception 'Your location is not accurate enough. Step outside, away from the building, and try again';
  end if;
  if public.distance_metres(p_lat, p_lng, due.lat, due.lng) > 200 then
    raise exception 'Name the place from where you clocked in: you are % m away', round(public.distance_metres(p_lat, p_lng, due.lat, due.lng)::numeric);
  end if;

  -- The sign photo was taken where the place is being saved, and the
  -- selfie close by.
  select * into sign_at from public.position_point(p_evidence->'sign');
  if sign_at.lat is not null
     and public.distance_metres(p_lat, p_lng, sign_at.lat, sign_at.lng)
         > greatest(30, p_accuracy_m + coalesce(sign_at.accuracy_m, 0)) then
    raise exception 'Your location moved while you took the photo of the sign. Stand still outside and take it again';
  end if;
  select * into selfie_at from public.position_point(p_evidence->'selfie');
  if selfie_at.lat is not null
     and public.distance_metres(p_lat, p_lng, selfie_at.lat, selfie_at.lng)
         > greatest(100, p_accuracy_m + coalesce(selfie_at.accuracy_m, 0)) then
    raise exception 'Take the selfie at the place, next to the sign';
  end if;

  if p_storefront_path is null or not public.photo_is_fresh('reports', p_storefront_path, 30)
     or not exists (select 1 from public.photo_checks c where c.path = p_storefront_path
                    and c.kind = 'storefront' and c.verdict in ('pass', 'unchecked')) then
    raise exception 'Take the photo of the store sign from outside, in the app';
  end if;
  if p_selfie_path is null or not public.photo_is_fresh('reports', p_selfie_path, 30)
     or not exists (select 1 from public.photo_checks c where c.path = p_selfie_path
                    and c.kind = 'product_selfie' and c.verdict in ('pass', 'unchecked')) then
    raise exception 'Take the selfie holding our product, in the app';
  end if;
  if exists (select 1 from public.known_places k
             where k.photo_path in (p_storefront_path, p_selfie_path)
                or k.selfie_path in (p_storefront_path, p_selfie_path)) then
    raise exception 'Take new photos here';
  end if;

  -- A name that belongs to a store or place somewhere else is refused (025).
  select x.name into clash from (
    select o.name, public.distance_metres(p_lat, p_lng, o.lat, o.lng) as m
    from public.outlets o where o.is_active and o.lat is not null and public.names_overlap(o.name, clean)
    union all
    select k.name, public.distance_metres(p_lat, p_lng, k.lat, k.lng)
    from public.known_places k where k.verified and public.names_overlap(k.name, clean)
  ) x where x.m > 500 order by x.m limit 1;
  if clash is not null then
    raise exception 'That name does not match where you are standing. Type the name on the sign here';
  end if;

  select k.id, k.source into here from public.known_place_at(p_lat, p_lng) k;
  if here.id is not null and here.source = 'clock_in' then
    -- The guess from a clock-in (034) gets its real name and photos.
    update public.known_places
    set name = clean, source = 'staff', named_by = me, photo_path = p_storefront_path,
        selfie_path = p_selfie_path, position_evidence = p_evidence, lat = p_lat, lng = p_lng, last_seen_at = now(),
        visitors = case when me = any(visitors) then visitors else visitors || me end
    where id = here.id;
    place := here.id;
  elsif here.id is not null then
    -- Named by someone else since: nothing to add.
    place := here.id;
  elsif public.outlet_containing(p_lat, p_lng) is null then
    place := public.learn_place(p_lat, p_lng, clean, null, 'staff', p_storefront_path);
    update public.known_places set selfie_path = p_selfie_path, position_evidence = p_evidence where id = place;
  end if;

  update public.place_naming_due
  set named_at = now(), place_id = place
  where user_id = me and named_at is null and dismissed_at is null
    and (id = due.id or public.distance_metres(lat, lng, p_lat, p_lng) <= 200);
  return place;
end;
$$;


--
-- Name: names_overlap(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.names_overlap(a text, b text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select length(public.place_key(a)) >= 6 and length(public.place_key(b)) >= 6
     and (' ' || public.place_key(a) || ' ' like '% ' || public.place_key(b) || ' %'
          or ' ' || public.place_key(b) || ' ' like '% ' || public.place_key(a) || ' %');
$$;


--
-- Name: nearest_outlet_for_user(uuid, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nearest_outlet_for_user(target uuid, p_lat double precision, p_lng double precision) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.id
  from public.outlets o
  where o.id in (select outlet_id from public.outlets_for_user(target))
  order by public.distance_metres(p_lat, p_lng, o.lat, o.lng) nulls last
  limit 1;
$$;


--
-- Name: no_show_already_reported(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.no_show_already_reported(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.notifications n
    where n.audience_detail ->> 'kind' = 'no_show'
      and n.audience_detail ->> 'subject_id' = p_user::text
      and (n.created_at at time zone 'Africa/Lagos')::date = public.business_date()
  );
$$;


--
-- Name: note_place_visit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_place_visit(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  place record;
begin
  if me is null then
    return;
  end if;
  update public.known_places
  set times_seen = times_seen + 1, last_seen_at = now(),
      visitors = case when me = any(visitors) then visitors else visitors || me end
  where id = p_id
  returning id, name, source, verified, named_by, visitors, times_seen into place;

  if place.id is not null and place.source = 'staff' and not place.verified
     and place.named_by = me and place.visitors = array[me] and place.times_seen >= 3
     and not exists (select 1 from public.integrity_flags f
                     where f.kind = 'own_named_place' and f.detail->>'place_id' = place.id::text) then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail)
    values (me, 'own_named_place', 'medium',
            format('Keeps being found at "%s", a place they named themselves that nobody else has visited',
                   place.name),
            jsonb_build_object('place_id', place.id, 'times', place.times_seen));
  end if;
end;
$$;


--
-- Name: notification_sent_by_me(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_sent_by_me(p_notification uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.notifications n
    where n.id = p_notification and n.sender_id = auth.uid() and n.sender_id is not null
  );
$$;


--
-- Name: office_name(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.office_name(p uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select pr.full_name
  from public.profiles pr
  where pr.id = p
    and pr.role in ('admin'::user_role, 'supervisor'::user_role)
    and public.can_send_notifications();
$$;


--
-- Name: open_support_thread(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_support_thread(p_subject text, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  uid uuid := auth.uid();
  my_outlet uuid;
  tid uuid;
begin
  if uid is null then raise exception 'Not authenticated'; end if;
  if coalesce(btrim(p_body), '') = '' then raise exception 'Message is empty'; end if;

  select outlet_id into my_outlet from public.profiles where id = uid;

  insert into public.support_threads (user_id, outlet_id, subject)
  values (uid, my_outlet,
          left(coalesce(nullif(btrim(p_subject), ''), 'Issue from the field'), 160))
  returning id into tid;

  insert into public.support_messages (thread_id, sender_id, sender_role, body)
  values (tid, uid, 'staff', left(btrim(p_body), 4000));

  return tid;
end;
$$;


--
-- Name: outlet_containing(double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outlet_containing(p_lat double precision, p_lng double precision) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.id
  from public.outlets o
  where o.is_active
    and public.distance_metres(p_lat, p_lng, o.lat, o.lng) <= o.geofence_radius_m
  order by public.distance_metres(p_lat, p_lng, o.lat, o.lng)
  limit 1;
$$;


--
-- Name: outlets_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outlets_for_user(target uuid) RETURNS TABLE(outlet_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.id
  from public.outlets o
  where o.is_active
    and (o.id in (select s.outlet_id from public.staff_outlets s where s.user_id = target)
         or o.id = (select p.outlet_id from public.profiles p where p.id = target));
$$;


