-- Name: owns_count_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owns_count_request(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
