--
-- Name: photo_is_fresh(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.photo_is_fresh(p_bucket text, p_path text, p_minutes integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $$
  select auth.uid() is not null
     and p_path like auth.uid()::text || '/%'
     and exists (
       select 1 from storage.objects o
       where o.bucket_id = p_bucket
         and o.name = p_path
         and o.created_at >= now() - make_interval(mins => p_minutes)
     )
     and coalesce(public.photo_verdict(p_path), 'none') in ('pass', 'unchecked');
$$;


