$$;


--
-- Name: pin_store_from_place(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pin_store_from_place(p_place uuid, p_outlet uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  place record;
begin
  if not public.is_admin() then
    raise exception 'Only an admin can confirm a store''s location';
  end if;

  select k.lat, k.lng, k.address into place from public.known_places k where k.id = p_place;
  if place is null then
    raise exception 'That place no longer exists';
  end if;

  update public.outlets
  set lat = place.lat, lng = place.lng, address = coalesce(place.address, address)
  where id = p_outlet and lat is null;
  if not found then
    raise exception 'That store already has a location. Change it on the Outlets page';
  end if;

  delete from public.known_places where id = p_place;
  update public.known_places
  set store_candidates = array_remove(store_candidates, p_outlet)
  where p_outlet = any(store_candidates);
end;
$$;


--
-- Name: ping_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ping_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.offline then
    return new;
  end if;
  if new.distance_m is not null and new.distance_m > 300 then
    -- One left_geofence alert per shift per 30 minutes.
    if not exists (
      select 1 from public.location_alerts
      where user_id = new.user_id
        and alert_type = 'left_geofence'
        and created_at > now() - interval '30 minutes'
    ) then
      insert into public.location_alerts (user_id, attendance_id, alert_type, distance_m)
      values (new.user_id, new.attendance_id, 'left_geofence', new.distance_m);
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: ping_enforce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ping_enforce() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  open_shift record;
  previous_at timestamptz;
  taken_day date;
begin
  new.user_id := auth.uid();
  new.received_at := now();
  if coalesce(current_setting('xtend.offline_ping', true), '') = 'on' and new.created_at is not null then
    new.offline := true;
  else
    new.offline := false;
    new.created_at := now();
  end if;
  taken_day := (new.created_at at time zone 'Africa/Lagos')::date;

  -- Anchor to that day's opening event; a ping without an open shift is
  -- kept but carries no distance.
  select a.id, a.lat, a.lng into open_shift
  from public.attendance a
  where a.user_id = new.user_id
    and a.attendance_date = taken_day
    and a.type = 'opening'
  limit 1;

  if open_shift.id is not null then
    new.attendance_id := open_shift.id;
    new.distance_m := public.distance_metres(new.lat, new.lng, open_shift.lat, open_shift.lng);
  end if;

  select max(p.created_at) into previous_at
  from public.location_pings p
  where p.user_id = new.user_id
    and p.created_at <= new.created_at
    and p.created_at >= (taken_day::timestamp at time zone 'Africa/Lagos');

  if previous_at is not null then
    new.gap_seconds := greatest(0, extract(epoch from (new.created_at - previous_at))::integer);
  end if;

  return new;
end;
$$;


--
-- Name: ping_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ping_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
