--
-- Name: place_is_recognised(double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_is_recognised(p_lat double precision, p_lng double precision) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
