--
-- Name: place_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select btrim(regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', ' ', 'g'))
$$;


--
-- Name: position_point(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.position_point(p jsonb) RETURNS TABLE(lat double precision, lng double precision, accuracy_m double precision)
    LANGUAGE sql IMMUTABLE
    AS $$
  select (p->>'lat')::float8, (p->>'lng')::float8, (p->>'accuracy_m')::float8
  where jsonb_typeof(p) = 'object'
    and jsonb_typeof(p->'lat') = 'number' and jsonb_typeof(p->'lng') = 'number'
    and jsonb_typeof(p->'accuracy_m') = 'number'
    and abs((p->>'lat')::float8) <= 90 and abs((p->>'lng')::float8) <= 180
    and (p->>'accuracy_m')::float8 >= 0;
$$;


--
-- Name: post_support_message(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_support_message(p_thread uuid, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  uid uuid := auth.uid();
  t record;
  role_val support_sender;
  mid uuid;
begin
  if uid is null then raise exception 'Not authenticated'; end if;
  if coalesce(btrim(p_body), '') = '' then raise exception 'Message is empty'; end if;

  select * into t from public.support_threads where id = p_thread;
  if t.id is null then raise exception 'No such thread'; end if;

  if t.user_id = uid then
    role_val := 'staff';
  elsif public.is_admin() then
    role_val := 'admin';
  elsif public.supervises_user(t.user_id) then
    role_val := 'supervisor';
  else
    raise exception 'That thread is not yours';
  end if;

  insert into public.support_messages (thread_id, sender_id, sender_role, body)
  values (p_thread, uid, role_val, left(btrim(p_body), 4000))
  returning id into mid;

  update public.support_threads
  set last_message_at = now(),
      -- The member writing again needs attention; the office writing has
      -- given it. Neither closes the thread: that is an explicit action.
      status = case when role_val = 'staff' then 'open'::support_status
                    else 'ai_answered'::support_status end
  where id = p_thread;

  return mid;
end;
$$;


--
-- Name: product_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.product_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select lower(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g'))
$$;


--
-- Name: profiles_self_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_self_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or public.is_admin() or new.id <> auth.uid() then
    return new;
  end if;
  new.role          := old.role;
  new.staff_role_id := old.staff_role_id;
  new.outlet_id     := old.outlet_id;
  new.supervisor_id := old.supervisor_id;
  new.is_active     := old.is_active;
  new.push_exempt   := old.push_exempt;
  if coalesce(current_setting('xtend.own_photo', true), '') <> 'on' then
    new.avatar_path := old.avatar_path;
  end if;
  return new;
end;
$$;


--
-- Name: profiles_staff_role_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_staff_role_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  base user_role;
begin
  if new.staff_role_id is not null then
    if tg_op = 'UPDATE'
       and new.role is distinct from old.role
       and new.staff_role_id is not distinct from old.staff_role_id then
      -- The role was changed on its own: the added role no longer applies.
      new.staff_role_id := null;
    else
      select r.base_role into base from public.staff_roles r where r.id = new.staff_role_id;
      new.role := base;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: profiles_supervisor_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_supervisor_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.supervisor_id is null then
    return new;
  end if;
  if new.supervisor_id = new.id then
    raise exception 'Somebody cannot supervise themselves';
  end if;
  if not exists (
    select 1 from public.profiles s
    where s.id = new.supervisor_id and s.role in ('supervisor'::user_role, 'admin'::user_role)
  ) then
    raise exception 'That person is not a supervisor';
  end if;
  return new;
end;
$$;


--
-- Name: punctuality_grace_minutes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.punctuality_grace_minutes() RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$ select 15 $$;


--
-- Name: raise_place_due(uuid, double precision, double precision, double precision, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_place_due(p_user uuid, p_lat double precision, p_lng double precision, p_accuracy double precision, p_kind text, p_source uuid, p_position jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  shot record;
  apart double precision;
  at_lat double precision := p_lat;
  at_lng double precision := p_lng;
  at_acc double precision := p_accuracy;
begin
  -- A rough fix cannot say which building; that is flagged elsewhere.
  if p_lat is null or p_lng is null or coalesce(p_accuracy, 1000) > 100 then
    return;
  end if;

  select * into shot from public.position_point(p_position->'shutter');
  if shot.lat is not null then
    apart := public.distance_metres(p_lat, p_lng, shot.lat, shot.lng);
    -- The two readings disagree: the spot is not certain enough to save.
    if apart > greatest(30, coalesce(p_accuracy, 0) + coalesce(shot.accuracy_m, 0)) then
      return;
    end if;
    -- Either reading inside a store or a known place: it is recognised.
    if public.place_is_recognised(shot.lat, shot.lng) then
      return;
    end if;
    -- The surer of the two is where the place is.
    if shot.accuracy_m < p_accuracy then
      at_lat := shot.lat; at_lng := shot.lng; at_acc := shot.accuracy_m;
    end if;
  end if;

  if public.place_is_recognised(p_lat, p_lng) then
    return;
  end if;
  -- Already asked about this spot today, or let off it (a dismissal holds
  -- for the rest of the day there).
  if exists (select 1 from public.place_naming_due d
             where d.user_id = p_user and d.due_date = public.business_date()
               and d.named_at is null
               and public.distance_metres(at_lat, at_lng, d.lat, d.lng) <= 150) then
    return;
  end if;
  insert into public.place_naming_due (user_id, lat, lng, accuracy_m, source_kind, source_id, due_date)
  values (p_user, at_lat, at_lng, at_acc, p_kind, p_source, public.business_date())
  on conflict do nothing;
end;
$$;


--
-- Name: record_background_pings(text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_background_pings(p_token text, p_points jsonb, p_sent_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  t record;
  offset_s integer := coalesce(extract(epoch from (p_sent_at - now()))::integer, 0);
  point jsonb;
  taken timestamptz;
  kept integer := 0;
  mocked integer := 0;
  la double precision;
  ln double precision;
  acc double precision;
  alert_before timestamptz;
  alert record;
  open_shift boolean;
begin
  select * into t from public.tracking_tokens
  where token_hash = encode(sha256(convert_to(coalesce(p_token, ''), 'utf8')), 'hex');
  if t.id is null or t.revoked_at is not null or t.expires_at < now() then
    return jsonb_build_object('ok', false, 'reason', 'token');
  end if;
  if not exists (select 1 from public.profiles where id = t.user_id and is_active) then
    return jsonb_build_object('ok', false, 'reason', 'token');
  end if;

  open_shift := exists (
    select 1 from public.attendance
    where user_id = t.user_id and attendance_date = public.business_date() and type = 'opening'
  ) and not exists (
    select 1 from public.attendance
    where user_id = t.user_id and attendance_date = public.business_date() and type = 'closing'
  );
  if not open_shift then
    update public.tracking_tokens set revoked_at = now() where id = t.id;
    return jsonb_build_object('ok', false, 'stop', true, 'shift_open', false);
  end if;

  if jsonb_typeof(p_points) <> 'array' or jsonb_array_length(p_points) > 500 then
    raise exception 'Send at most 500 positions at a time';
  end if;

  perform set_config('request.jwt.claim.sub', t.user_id::text, true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', t.user_id, 'role', 'authenticated')::text, true);

  select max(created_at) into alert_before from public.location_alerts
  where user_id = t.user_id and alert_type = 'left_geofence';

  for point in select * from jsonb_array_elements(p_points) order by (value->>'captured_at') loop
    taken := public.safe_ts(point->>'captured_at') - make_interval(secs => offset_s);
    if taken is null or taken > now() + interval '2 minutes' or taken < now() - interval '24 hours'
       or taken < t.created_at - interval '5 minutes'
       or jsonb_typeof(point->'lat') <> 'number' or jsonb_typeof(point->'lng') <> 'number'
       or jsonb_typeof(point->'accuracy_m') <> 'number' then
      continue;
    end if;
    la := (point->>'lat')::float8;
    ln := (point->>'lng')::float8;
    acc := (point->>'accuracy_m')::float8;
    if abs(la) > 90 or abs(ln) > 180 or acc < 0 then continue; end if;
    if (point->>'is_mock')::boolean is true then mocked := mocked + 1; end if;
    if exists (
      select 1 from public.location_pings l
      where l.user_id = t.user_id and l.created_at between taken - interval '1 second' and taken + interval '1 second'
    ) then continue; end if;

    if now() - taken <= interval '2 minutes' then
      perform set_config('xtend.offline_ping', 'off', true);
      insert into public.location_pings (lat, lng, accuracy_m) values (la, ln, acc);
    else
      perform set_config('xtend.offline_ping', 'on', true);
      insert into public.location_pings (lat, lng, accuracy_m, created_at) values (la, ln, acc, taken);
    end if;
    kept := kept + 1;
  end loop;
  perform set_config('xtend.offline_ping', 'off', true);

  if mocked > 0 and not exists (
    select 1 from public.integrity_flags
    where user_id = t.user_id and kind = 'mock_location_confirmed'
      and flag_date = public.business_date() and detail->>'source' = 'background'
  ) then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail)
    values (t.user_id, 'mock_location_confirmed', 'high',
            format('The phone said %s position%s sent while on shift came from a fake-location app',
                   mocked, case when mocked = 1 then '' else 's' end),
            jsonb_build_object('source', 'background', 'positions', mocked));
  end if;

  update public.tracking_tokens set last_used_at = now(), points = points + kept where id = t.id;

  select a.id, a.distance_m, l.id as ping_id, l.lat, l.lng into alert
  from public.location_alerts a
  left join lateral (
    select p.id, p.lat, p.lng from public.location_pings p
    where p.user_id = t.user_id and not p.offline order by p.created_at desc limit 1
  ) l on true
  where a.user_id = t.user_id and a.alert_type = 'left_geofence'
    and a.created_at > coalesce(alert_before, '-infinity')
  order by a.created_at desc limit 1;

  -- Re-check after processing to close the race with a simultaneous clock-out.
  open_shift := exists (
    select 1 from public.attendance
    where user_id = t.user_id and attendance_date = public.business_date() and type = 'opening'
  ) and not exists (
    select 1 from public.attendance
    where user_id = t.user_id and attendance_date = public.business_date() and type = 'closing'
  );
  if not open_shift then update public.tracking_tokens set revoked_at = now() where id = t.id; end if;

  return jsonb_build_object(
    'ok', true, 'user_id', t.user_id, 'kept', kept, 'shift_open', open_shift,
    'alert', case when alert.id is null then null else jsonb_build_object(
      'id', alert.id, 'distance_m', alert.distance_m, 'ping_id', alert.ping_id,
      'lat', alert.lat, 'lng', alert.lng) end
  );
end;
$$;


--
-- Name: record_beacon(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_beacon(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  me uuid := auth.uid();
  recent record;
  made record;
  why text := coalesce(p->>'reason', 'interval');
begin
  if me is null then
    raise exception 'Sign in first';
  end if;
  if why not in ('open', 'visible', 'hidden', 'online', 'interval') then
    why := 'interval';
  end if;

  -- Several in a few seconds (a page opening fires more than one event)
  -- are one report.
  select b.id, b.received_at into recent
  from public.device_beacons b
  where b.user_id = me and b.received_at > now() - interval '15 seconds' and b.reason = why
  order by b.received_at desc limit 1;
  if recent.id is not null then
    return jsonb_build_object('id', recent.id, 'server_time', recent.received_at);
  end if;

  insert into public.device_beacons (user_id, reason, connection, battery_pct, charging, outbox_count,
                                     oldest_queued_at, device_time, offline_since, lat, lng, accuracy_m)
  values (
    me, why,
    left(nullif(p->>'connection', ''), 20),
    case when (p->>'battery_pct') ~ '^\d{1,3}$' and (p->>'battery_pct')::int <= 100
         then (p->>'battery_pct')::smallint end,
    case when p->>'charging' in ('true', 'false') then (p->>'charging')::boolean end,
    case when (p->>'outbox_count') ~ '^\d{1,6}$' then (p->>'outbox_count')::int end,
    public.safe_ts(p->>'oldest_queued_at'),
    public.safe_ts(p->>'device_time'),
    public.safe_ts(p->>'offline_since'),
    case when jsonb_typeof(p->'lat') = 'number' and jsonb_typeof(p->'lng') = 'number'
          and abs((p->>'lat')::float8) <= 90 and abs((p->>'lng')::float8) <= 180
         then (p->>'lat')::float8 end,
    case when jsonb_typeof(p->'lat') = 'number' and jsonb_typeof(p->'lng') = 'number'
          and abs((p->>'lat')::float8) <= 90 and abs((p->>'lng')::float8) <= 180
         then (p->>'lng')::float8 end,
    case when jsonb_typeof(p->'accuracy_m') = 'number' and (p->>'accuracy_m')::float8 >= 0
         then (p->>'accuracy_m')::float8 end
  )
  returning id, received_at into made;
  return jsonb_build_object('id', made.id, 'server_time', made.received_at);
end;
$_$;


--
-- Name: record_excuse_check(uuid, text, timestamp with time zone, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_excuse_check(p_user uuid, p_claim text, p_from timestamp with time zone, p_to timestamp with time zone, p_verdict text, p_headline text, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare new_id uuid;
begin
  if not (public.is_admin() or public.supervises_user(p_user)) then
    raise exception 'You can only check your own team';
  end if;
  insert into public.excuse_checks (user_id, claim, window_from, window_to, verdict, headline, note, checked_by)
  values (p_user, p_claim, p_from, p_to, p_verdict, left(btrim(p_headline), 500),
          nullif(btrim(coalesce(p_note, '')), ''), auth.uid())
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: record_offline_pings(jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_offline_pings(p_points jsonb, p_sent_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  offset_s integer := coalesce(extract(epoch from (p_sent_at - now()))::integer, 0);
  point jsonb;
  taken timestamptz;
  kept integer := 0;
  faked integer := 0;
  lat double precision;
  lng double precision;
  acc double precision;
begin
  if me is null then
    raise exception 'Sign in first';
  end if;
  if jsonb_typeof(p_points) <> 'array' or jsonb_array_length(p_points) > 500 then
    raise exception 'Send at most 500 positions at a time';
  end if;

  perform set_config('xtend.offline_ping', 'on', true);
  for point in select * from jsonb_array_elements(p_points) loop
    taken := public.safe_ts(point->>'captured_at') - make_interval(secs => offset_s);
    if taken is null or taken > now() + interval '2 minutes' or taken < now() - interval '24 hours'
       or jsonb_typeof(point->'lat') <> 'number' or jsonb_typeof(point->'lng') <> 'number'
       or jsonb_typeof(point->'accuracy_m') <> 'number' then
      continue;
    end if;
    lat := (point->>'lat')::float8;
    lng := (point->>'lng')::float8;
    acc := (point->>'accuracy_m')::float8;
    if abs(lat) > 90 or abs(lng) > 180 or acc < 0 then
      continue;
    end if;

    -- The phone told us, well after this, that nothing was waiting.
    if exists (select 1 from public.device_beacons b
               where b.user_id = me and b.outbox_count = 0
                 and b.received_at > taken + interval '10 minutes'
                 and b.received_at < now() - interval '30 seconds') then
      faked := faked + 1;
      continue;
    end if;

    -- Already here (a retry after a dropped connection).
    if exists (select 1 from public.location_pings l
               where l.user_id = me and l.created_at between taken - interval '1 second'
                                                        and taken + interval '1 second') then
      continue;
    end if;

    insert into public.location_pings (lat, lng, accuracy_m, created_at)
    values (lat, lng, acc, taken);
    kept := kept + 1;
  end loop;
  perform set_config('xtend.offline_ping', 'off', true);

  if faked > 0 and not exists (
    select 1 from public.integrity_flags f
    where f.user_id = me and f.kind = 'backdated_clock' and f.flag_date = public.business_date()
      and f.detail->>'source' = 'offline_positions') then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail)
    values (me, 'backdated_clock', 'high',
            format('%s offline position%s claimed times from before the phone last said nothing was waiting to upload. They were made up afterwards and were not kept',
                   faked, case when faked = 1 then '' else 's' end),
            jsonb_build_object('source', 'offline_positions', 'refused', faked));
  end if;

  if abs(offset_s) > 300 and not exists (
    select 1 from public.integrity_flags f
    where f.user_id = me and f.kind = 'phone_clock_wrong' and f.flag_date = public.business_date()) then
    insert into public.integrity_flags (user_id, kind, severity, summary, detail)
    values (me, 'phone_clock_wrong', 'medium',
            format('The phone''s clock was %s minutes %s when it sent positions saved offline',
                   abs(offset_s) / 60, case when offset_s > 0 then 'ahead' else 'behind' end),
            jsonb_build_object('offset_s', offset_s, 'source', 'offline_positions'));
  end if;

  return kept;
end;
$$;


--
-- Name: record_selfie_sweep(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_selfie_sweep(p_result jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.job_runs set last_result = p_result where job = 'purge_selfies';
$$;


--
-- Name: release_reports_on_demotion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_reports_on_demotion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.role in ('supervisor'::user_role, 'admin'::user_role)
     and new.role not in ('supervisor'::user_role, 'admin'::user_role) then
    update public.profiles
    set supervisor_id = null
    where supervisor_id = new.id;
  end if;
  return new;
end;
$$;


--
-- Name: reopen_support_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_support_thread(p_thread uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  t record;
begin
  select * into t from public.support_threads where id = p_thread;
  if t.id is null then raise exception 'No such thread'; end if;
  if not (public.is_admin() or public.supervises_user(t.user_id)) then
    raise exception 'That thread is not yours to reopen';
  end if;
  if t.status <> 'resolved' then raise exception 'That thread is not closed'; end if;
  update public.support_threads
  set status = 'escalated', escalated_at = now(), resolved_at = null, resolved_by = null
  where id = p_thread;
end;
$$;


--
-- Name: report_app_install(text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_app_install(p_platform text, p_app_version text, p_app_build integer, p_web_build text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me uuid := auth.uid();
begin
  if me is null or p_platform not in ('android', 'ios', 'web') then
    return;
  end if;
  insert into public.app_installs (user_id, platform, app_version, app_build, web_build, last_seen)
  values (me, p_platform, left(nullif(p_app_version, ''), 40),
          case when p_app_build >= 0 then p_app_build end, left(nullif(p_web_build, ''), 80), now())
  on conflict (user_id, platform) do update
    set app_version = excluded.app_version,
        app_build = excluded.app_build,
        web_build = excluded.web_build,
        last_seen = now()
    where public.app_installs.last_seen < now() - interval '1 minute'
       or public.app_installs.app_build is distinct from excluded.app_build
       or public.app_installs.web_build is distinct from excluded.web_build;
end;
$$;


--
-- Name: report_enforce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_enforce() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if not public.can_file_report() then
      raise exception 'Only marketers file the daily report';
    end if;
    new.user_id     := auth.uid();
    new.report_date := public.business_date();
    select p.outlet_id into new.outlet_id
    from public.profiles p where p.id = new.user_id;
  else
    new.user_id     := old.user_id;
    new.report_date := old.report_date;
    new.outlet_id   := old.outlet_id;
    if old.report_date <> public.business_date() then
      raise exception 'Reports can only be edited on the day they were filed';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: report_photo_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_photo_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (select count(*) from public.report_photos where report_id = new.report_id) >= 5 then
    raise exception 'A report carries at most 5 photos';
  end if;
  return new;
end;
$$;


--
-- Name: request_phone_check(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_phone_check(p_user uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  made uuid;
begin
  if not (public.is_admin() or public.supervises_user(p_user)) then
    raise exception 'You can only check the phones of your own team';
  end if;
  -- One at a time: a check sent in the last two minutes is still running.
  select c.id into made from public.phone_checks c
  where c.user_id = p_user and c.created_at > now() - interval '2 minutes'
  order by c.created_at desc limit 1;
  if made is not null then
    return made;
  end if;
  insert into public.phone_checks (user_id, requested_by) values (p_user, auth.uid())
  returning id into made;
  return made;
end;
$$;


--
-- Name: request_store_count(uuid[], date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_store_count(p_user_ids uuid[], p_due_date date, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  me public.profiles;
  wanted uuid[] := coalesce(p_user_ids, '{}'::uuid[]);
  new_id uuid;
begin
  select * into me from public.profiles where id = auth.uid();
  if me.id is null or not me.is_active or me.role not in ('admin'::user_role, 'supervisor'::user_role) then
    raise exception 'Only a supervisor or an admin can ask for a store count';
  end if;
  if array_length(wanted, 1) is null then
    raise exception 'Pick at least one person to count';
  end if;
  if p_due_date is null or p_due_date < public.business_date() then
    raise exception 'The due date cannot be in the past';
  end if;
  if p_due_date > public.business_date() + 60 then
    raise exception 'The due date must be within 60 days';
  end if;

  if exists (
    select 1 from unnest(wanted) as w(id)
    left join public.profiles p on p.id = w.id
    where p.id is null
       or not p.is_active
       or p.role not in ('merchandiser'::user_role, 'marketer'::user_role)
       or not (me.role = 'admin' or public.supervises_user(p.id))
  ) then
    raise exception 'You can only ask your own active merchandisers and marketers to count';
  end if;
  if exists (select 1 from unnest(wanted) as w(id) where not public.person_counts_stock(w.id)) then
    raise exception 'Someone you picked is in a role that does not take store counts';
  end if;

  insert into public.count_requests (requested_by, due_date, note)
  values (me.id, p_due_date, nullif(btrim(coalesce(p_note, '')), ''))
  returning id into new_id;

  insert into public.count_request_targets (request_id, user_id)
  select distinct new_id, w.id from unnest(wanted) as w(id);

  insert into public.audit_log (actor_id, action, target_table, target_id, meta)
  values (me.id, 'store_count.request', 'count_requests', new_id,
          jsonb_build_object('user_ids', to_jsonb(wanted), 'due_date', p_due_date));

  return new_id;
end;
$$;


--
-- Name: resolve_alert(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_alert(p_alert_id uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Admins only';
  end if;

  update public.location_alerts
  set is_resolved = true,
      resolved_by = auth.uid(),
      resolved_at = now(),
      note        = p_note
  where id = p_alert_id;

  if not found then
    raise exception 'Alert not found';
  end if;

  perform public.write_audit(
    'alert.resolve', 'location_alerts', p_alert_id,
    jsonb_build_object('note', p_note)
  );
end;
$$;


--
-- Name: resolve_alerts(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_alerts(p_alert_ids uuid[], p_note text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  done uuid;
  n integer := 0;
begin
  if not public.is_admin() then
    raise exception 'Admins only';
  end if;
  if coalesce(array_length(p_alert_ids, 1), 0) = 0 then
    return 0;
  end if;
  if array_length(p_alert_ids, 1) > 500 then
    raise exception 'Resolve at most 500 alerts at a time';
  end if;

  for done in
    update public.location_alerts
    set is_resolved = true,
        resolved_by = auth.uid(),
        resolved_at = now(),
        note        = p_note
    where id = any(p_alert_ids) and not is_resolved
    returning id
  loop
    perform public.write_audit(
      'alert.resolve', 'location_alerts', done,
      jsonb_build_object('note', p_note, 'together_with', array_length(p_alert_ids, 1))
    );
    n := n + 1;
  end loop;

  return n;
end;
$$;


--
-- Name: resolve_notification_targets(public.notification_audience, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_notification_targets(p_audience public.notification_audience, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(user_id uuid, full_name text, role public.user_role, outlet_name text, devices integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id,
    p.full_name,
    p.role,
    o.name,
    (select count(*)::int from public.push_subscriptions s
      where s.user_id = p.id and s.is_active)
  from public.profiles p
  left join public.outlets o on o.id = p.outlet_id
  where public.can_send_notifications()
    and p.is_active
    -- An admin reaches everyone. A supervisor reaches the field staff at
    -- their own outlet: not other supervisors, not admins, not themselves.
    and (
      public.is_admin()
      or (public.supervises_user(p.id) and public.is_field_role(p.role) and p.id <> auth.uid())
    )
    and case p_audience
          when 'everyone' then true
          when 'role' then p.role::text = (p_detail ->> 'role')
          when 'outlet' then p.outlet_id = (p_detail ->> 'outlet_id')::uuid
          when 'users' then p.id = any (
            select (jsonb_array_elements_text(coalesce(p_detail -> 'user_ids', '[]'::jsonb)))::uuid
          )
        end
  order by p.full_name;
$$;


--
-- Name: resolve_support_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_support_thread(p_thread uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  t record;
begin
  select * into t from public.support_threads where id = p_thread;
  if t.id is null then raise exception 'No such thread'; end if;
  if not (public.is_admin() or public.supervises_user(t.user_id)) then
    raise exception 'That thread is not yours to resolve';
  end if;

  update public.support_threads
  set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
  where id = p_thread;
end;
$$;


--
-- Name: review_integrity_flag(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_integrity_flag(p_id uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.integrity_flags f
  set reviewed_by = auth.uid(), reviewed_at = now(),
      review_note = nullif(btrim(coalesce(p_note, '')), '')
  where f.id = p_id
    and (public.is_admin() or public.supervises_user(f.user_id));
  if not found then
    raise exception 'That flag is not yours to review';
  end if;
end;
$$;


--
-- Name: review_integrity_flags(uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_integrity_flags(p_ids uuid[], p_note text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  done integer;
begin
  if auth.uid() is null or coalesce(public.current_user_role()::text, '') not in ('admin', 'supervisor') then
    raise exception 'Only admins and supervisors review flags';
  end if;
  if p_ids is null or cardinality(p_ids) = 0 then
    raise exception 'Pick at least one flag';
  end if;
  if cardinality(p_ids) > 200 then
    raise exception 'Review at most 200 flags at a time';
  end if;
  if p_note is not null and length(btrim(p_note)) > 500 then
    raise exception 'Keep the note under 500 characters';
  end if;

  update public.integrity_flags f
  set reviewed_by = auth.uid(), reviewed_at = now(),
      review_note = nullif(btrim(coalesce(p_note, '')), '')
  where f.id = any(p_ids)
    and f.reviewed_at is null
    and (public.is_admin() or public.supervises_user(f.user_id));
  get diagnostics done = row_count;
  return done;
end;
$$;


--
-- Name: revoke_tracking_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_tracking_tokens() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.tracking_tokens set revoked_at = now()
  where user_id = auth.uid() and revoked_at is null;
$$;


