--
-- Name: schedule_notification(text, text, text, public.notification_audience, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_notification(p_title text, p_body text, p_url text, p_audience public.notification_audience, p_detail jsonb, p_send_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  ids uuid[];
  sid uuid;
begin
  if not public.can_send_notifications() then raise exception 'Admins and supervisors only'; end if;
  if p_send_at is null or p_send_at < now() + interval '2 minutes' then
    raise exception 'Pick a time at least a few minutes from now';
  end if;
  if p_send_at > now() + interval '60 days' then
    raise exception 'Pick a time within the next 60 days';
  end if;
  select array_agg(r.user_id) into ids
  from public.resolve_notification_targets(p_audience, coalesce(p_detail, '{}'::jsonb)) r;
  if coalesce(array_length(ids, 1), 0) = 0 then raise exception 'That audience matches nobody'; end if;

  insert into public.scheduled_notifications
    (created_by, title, body, url, audience, audience_detail, user_ids, send_at)
  values (auth.uid(), btrim(p_title), btrim(p_body), nullif(btrim(coalesce(p_url, '')), ''),
          p_audience, coalesce(p_detail, '{}'::jsonb), ids, p_send_at)
  returning id into sid;
  return sid;
end;
$$;


--
-- Name: selfie_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.selfie_check() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return new;
  end if;

  if new.selfie_path is null then
    if tg_table_name = 'attendance' then
      raise exception 'A clock-in needs a selfie taken in the app';
    end if;
    return new;
  end if;

  if public.photo_verdict(new.selfie_path) = 'reject' then
    raise exception 'That selfie was rejected. Take a new one, live, of your face';
  end if;
  if public.photo_verdict(new.selfie_path) is null then
    raise exception 'The selfie has not been checked. Take it again in the app';
  end if;

  if not public.photo_is_fresh('selfies', new.selfie_path, 30)
     or (new.thumb_path is not null and not public.photo_is_fresh('selfies', new.thumb_path, 30)) then
    raise exception 'The selfie must be taken in the app just now';
  end if;

  if public.photo_already_used(new.selfie_path)
     or (new.thumb_path is not null and public.photo_already_used(new.thumb_path)) then
    raise exception 'That selfie has already been used';
  end if;

  return new;
end;
$$;


--
-- Name: selfie_retention_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.selfie_retention_status() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when public.is_admin() then jsonb_build_object(
    'last_run_at', (select last_run_at from public.job_runs where job = 'purge_selfies'),
    'last_result', (select last_result from public.job_runs where job = 'purge_selfies'),
    'photos_held', (
      (select count(*) from public.attendance where selfie_path is not null)
      + (select count(*) from public.store_visits where selfie_path is not null)
    ),
    'overdue', (
      (select count(*) from public.attendance
        where selfie_path is not null and created_at < now() - interval '24 hours')
      + (select count(*) from public.store_visits
        where selfie_path is not null and created_at < now() - interval '24 hours')
    )
  ) end;
$$;


--
-- Name: set_count_sheet_template(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_count_sheet_template(p_path text, p_file_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $$
declare
  obj record;
  clean_name text := left(btrim(regexp_replace(coalesce(p_file_name, ''), '[\r\n\t/\\]+', ' ', 'g')), 200);
  new_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an admin can change the count sheet';
  end if;

  select o.metadata->>'mimetype' as mimetype, (o.metadata->>'size')::bigint as size
    into obj
  from storage.objects o
  where o.bucket_id = 'reports'
    and o.name = p_path
    and p_path like auth.uid()::text || '/%'
    and o.created_at >= now() - interval '30 minutes';
  if not found then
    raise exception 'Upload the count sheet again, then save it';
  end if;
  if lower(coalesce(obj.mimetype, '')) <> 'application/pdf' then
    raise exception 'The count sheet must be a PDF';
  end if;
  if coalesce(obj.size, 0) <= 0 or obj.size > 10 * 1024 * 1024 then
    raise exception 'The count sheet must be smaller than 10 MB';
  end if;

  insert into public.count_sheet_templates (path, file_name, size_bytes, uploaded_by)
  values (p_path, coalesce(nullif(clean_name, ''), 'Count sheet.pdf'), obj.size, auth.uid())
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: set_my_avatar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_avatar(p_path text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'Not authenticated';
  end if;
  if p_path is null or p_path not like uid::text || '/%' then
    raise exception 'That photo is not yours';
  end if;
  if not exists (select 1 from storage.objects where bucket_id = 'avatars' and name = p_path) then
    raise exception 'Upload the photo first';
  end if;
  perform set_config('xtend.own_photo', 'on', true);
  update public.profiles set avatar_path = p_path where id = uid;
end;
$$;


--
-- Name: set_staff_outlets(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_staff_outlets(p_user_id uuid, p_outlet_ids uuid[]) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  wanted uuid[] := coalesce(p_outlet_ids, '{}'::uuid[]);
begin
  if not public.can_allocate_outlets(p_user_id) then
    raise exception 'You cannot change that person''s stores';
  end if;

  if exists (
    select 1 from unnest(wanted) as w(id)
    where not exists (select 1 from public.outlets o where o.id = w.id and o.is_active)
  ) then
    raise exception 'One of those stores does not exist or is no longer active';
  end if;

  delete from public.staff_outlets
  where user_id = p_user_id and outlet_id <> all (wanted);

  insert into public.staff_outlets (user_id, outlet_id, assigned_by)
  select p_user_id, w.id, auth.uid() from unnest(wanted) as w(id)
  on conflict (user_id, outlet_id) do nothing;

  -- Supervisors may allocate but may not call write_audit, so the row is
  -- written here where the trail cannot be skipped.
  insert into public.audit_log (actor_id, action, target_table, target_id, meta)
  values (auth.uid(), 'staff.allocate_outlets', 'staff_outlets', p_user_id,
          jsonb_build_object('outlet_ids', to_jsonb(wanted), 'count', array_length(wanted, 1)));

  return query
    select s.outlet_id from public.staff_outlets s where s.user_id = p_user_id;
end;
$$;


--
-- Name: staff_analytics(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_analytics(p_from date, p_to date) RETURNS TABLE(user_id uuid, full_name text, outlet_name text, days_present integer, days_late integer, days_off_site integer, avg_distance_m double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.id,
    p.full_name,
    o.name,
    count(*) filter (where a.type = 'opening')::int,
    count(*) filter (
      where a.type = 'opening' and o.shift_start is not null
        and (a.created_at at time zone 'Africa/Lagos')::time > o.shift_start
    )::int,
    count(*) filter (where a.type = 'opening' and a.status <> 'on_site')::int,
    round(avg(a.distance_m) filter (where a.type = 'opening')::numeric, 1)::double precision
  from public.profiles p
  left join public.outlets o on o.id = p.outlet_id
  left join public.attendance a
    on a.user_id = p.id and a.attendance_date between p_from and p_to
  where public.is_field_role(p.role)
    and (public.is_admin() or public.supervises_user(p.id))
  group by p.id, p.full_name, o.name
  order by p.full_name;
$$;


--
-- Name: staff_day(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_day(p_date date DEFAULT NULL::date) RETURNS TABLE(user_id uuid, staff_name text, role public.user_role, clocked_in_at timestamp with time zone, clocked_in_at_place text, clocked_out_at timestamp with time zone, clocked_out_at_place text, stores_visited integer, minutes_in_store integer, still_in_store text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with d as (select coalesce(p_date, public.business_date()) as day),
  people as (
    select pr.id, pr.full_name, pr.role
    from public.profiles pr, d
    where public.is_field_role(pr.role)
      and (public.is_admin() or public.supervises_user(pr.id) or pr.id = auth.uid())
      and (
        exists (select 1 from public.attendance a
                where a.user_id = pr.id and a.attendance_date = d.day)
        or exists (select 1 from public.store_visits v
                   where v.user_id = pr.id and v.visit_date = d.day)
      )
  )
  select
    pe.id,
    pe.full_name,
    pe.role,
    opening.created_at,
    opening.place_name,
    closing.created_at,
    closing.place_name,
    coalesce(vis.n, 0)::int,
    coalesce(vis.mins, 0)::int,
    vis.open_store
  from people pe
  cross join d
  left join lateral (
    select a.created_at, a.place_name from public.attendance a
    where a.user_id = pe.id and a.attendance_date = d.day and a.type = 'opening'
    limit 1
  ) opening on true
  left join lateral (
    select a.created_at, a.place_name from public.attendance a
    where a.user_id = pe.id and a.attendance_date = d.day and a.type = 'closing'
    limit 1
  ) closing on true
  left join lateral (
    select
      count(*) as n,
      sum(sv.minutes) as mins,
      max(case when sv.status = 'open' then sv.store_label end) as open_store
    from public.store_visit_detail sv
    where sv.user_id = pe.id and sv.visit_date = d.day
  ) vis on true
  order by opening.created_at nulls last, pe.full_name;
$$;


--
-- Name: staff_no_show(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_no_show(p_grace_minutes integer DEFAULT 30) RETURNS TABLE(user_id uuid, full_name text, phone text, outlet_id uuid, outlet_name text, shift_start time without time zone, minutes_late integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with now_local as (
    select (now() at time zone 'Africa/Lagos') as ts
  )
  select
    p.id,
    p.full_name,
    p.phone,
    o.id,
    o.name,
    o.shift_start,
    (extract(epoch from ((select ts from now_local) - ((select ts from now_local)::date + o.shift_start))) / 60)::int
  from public.profiles p
  join public.outlets o on o.id = p.outlet_id
  where p.is_active
    and public.is_field_role(p.role)
    and o.is_active
    and (select ts from now_local)
        >= ((select ts from now_local)::date + o.shift_start + make_interval(mins => greatest(0, p_grace_minutes)))
    and not exists (
      select 1 from public.attendance a
      where a.user_id = p.id
        and a.attendance_date = public.business_date()
        and a.type = 'opening'
    )
  order by o.name, p.full_name;
$$;


--
-- Name: store_count_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_count_status() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with req as (select * from public.my_open_count_request())
  select case
    when not public.can_count_stock() then
      jsonb_build_object('open', false, 'reason', 'not_allowed')
    when exists (select 1 from req) then
      (select jsonb_build_object('open', true, 'reason', 'request', 'request_id', req.id,
                                 'due_date', req.due_date, 'note', req.note,
                                 'requested_by', req.requested_by_name) from req)
    when public.is_month_end_window() then
      jsonb_build_object('open', true, 'reason', 'month_end',
        'due_date', ((date_trunc('month', public.business_date()) + interval '1 month')::date - 1))
    else
      jsonb_build_object('open', false, 'reason', 'none',
        'next_month_end', ((date_trunc('month', public.business_date()) + interval '1 month')::date
                           - public.month_end_count_days()))
  end;
$$;


--
-- Name: store_visit_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_visit_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.arrived_accuracy_m > 100 then
    insert into public.location_alerts (user_id, alert_type, distance_m)
    values (new.user_id, 'low_accuracy'::alert_type, new.arrived_distance_m);
  elsif new.arrived_status = 'off_site' then
    insert into public.location_alerts (user_id, alert_type, distance_m)
    values (new.user_id, 'off_site_clock'::alert_type, new.arrived_distance_m);
  end if;
  return new;
end;
$$;


--
-- Name: store_visit_enforce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_visit_enforce() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  o record;
begin
  if not public.can_visit_stores() then
    raise exception 'Only marketers record store visits';
  end if;

  new.user_id    := auth.uid();
  new.created_at := now();
  new.arrived_at := now();
  new.visit_date := public.business_date();
  new.status     := 'open';

  new.departed_at := null;
  new.departed_lat := null;
  new.departed_lng := null;
  new.departed_distance_m := null;
  new.departed_status := null;

  if new.outlet_id is null then
    new.outlet_id := public.outlet_containing(new.arrived_lat, new.arrived_lng);
  end if;

  if new.outlet_id is null then
    new.outlet_lat := null;
    new.outlet_lng := null;
    new.outlet_radius_m := null;
    new.arrived_distance_m := null;
    new.arrived_status := case
      when new.arrived_accuracy_m > 100 then 'flagged'::attendance_status
      else null
    end;
  else
    select lat, lng, geofence_radius_m, is_active into o
    from public.outlets where id = new.outlet_id;

    if o is null then
      raise exception 'That store does not exist';
    end if;
    if not o.is_active then
      raise exception 'That store is no longer active';
    end if;

    new.outlet_lat      := o.lat;
    new.outlet_lng      := o.lng;
    new.outlet_radius_m := o.geofence_radius_m;
    new.arrived_distance_m :=
      public.distance_metres(new.arrived_lat, new.arrived_lng, o.lat, o.lng);

    new.arrived_status := case
      when new.arrived_accuracy_m > 100 then 'flagged'::attendance_status
      when new.arrived_distance_m is null then null
      when new.arrived_distance_m <= o.geofence_radius_m then 'on_site'::attendance_status
      else 'off_site'::attendance_status
    end;
  end if;

  if new.client_captured_at > now() + interval '2 minutes'
     or new.client_captured_at < now() - interval '24 hours' then
    raise exception 'Invalid capture timestamp';
  end if;

  return new;
end;
$$;


--
-- Name: store_visits_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_visits_today() RETURNS SETOF public.store_visit_detail
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from public.store_visit_detail v
  where v.visit_date = public.business_date()
    and (public.is_admin() or public.supervises_user(v.user_id) or v.user_id = auth.uid())
  order by v.arrived_at desc;
$$;


--
-- Name: submit_count_sheet(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_count_sheet(p_outlet_id uuid, p_path text, p_file_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'storage'
    AS $$
declare
  status jsonb := public.store_count_status();
  obj record;
  kind text;
  clean_name text := left(btrim(regexp_replace(coalesce(p_file_name, ''), '[\r\n\t/\\]+', ' ', 'g')), 200);
  new_id uuid;
begin
  if not public.can_count_stock() then
    raise exception 'You cannot submit a store count';
  end if;
  if not coalesce((status->>'open')::boolean, false) then
    raise exception 'No store count is due: counts are taken when a supervisor asks, or at the end of the month';
  end if;
  if p_outlet_id is null
     or p_outlet_id not in (select outlet_id from public.outlets_for_user(auth.uid())) then
    raise exception 'That store is not one of yours';
  end if;

  -- Uploaded into their own folder in the last 30 minutes. (Not
  -- photo_is_fresh(): that also wants a photo check, which a PDF never has.)
  select o.metadata->>'mimetype' as mimetype, (o.metadata->>'size')::bigint as size
    into obj
  from storage.objects o
  where o.bucket_id = 'reports'
    and o.name = p_path
    and p_path like auth.uid()::text || '/%'
    and o.created_at >= now() - interval '30 minutes';
  if not found then
    raise exception 'Upload the filled count sheet again, then send it';
  end if;
  if exists (select 1 from public.store_count_sheets s where s.path = p_path) then
    raise exception 'That file has already been sent';
  end if;

  kind := lower(coalesce(obj.mimetype, ''));
  if kind not in ('application/pdf', 'image/jpeg', 'image/png',
                  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') then
    raise exception 'Send the count sheet as the Excel file, a PDF, or a photo of it (JPG or PNG)';
  end if;
  if coalesce(obj.size, 0) <= 0 or obj.size > 10 * 1024 * 1024 then
    raise exception 'The count sheet must be smaller than 10 MB';
  end if;

  insert into public.store_count_sheets
    (user_id, outlet_id, count_date, request_id, path, file_name, content_type, size_bytes)
  values
    (auth.uid(), p_outlet_id, public.business_date(),
     nullif(status->>'request_id', '')::uuid, p_path,
     coalesce(nullif(clean_name, ''), 'Count sheet'), kind, obj.size)
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: submit_store_count(uuid, jsonb, double precision, double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_store_count(p_outlet_id uuid, p_lines jsonb, p_lat double precision, p_lng double precision, p_accuracy_m double precision, p_photo_path text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  today date := public.business_date();
  status jsonb := public.store_count_status();
  req uuid := nullif(status->>'request_id', '')::uuid;
  store record;
  dist double precision;
  saved integer;
  lines jsonb;
begin
  if not public.can_count_stock() then
    raise exception 'You cannot submit a store count';
  end if;
  if not coalesce((status->>'open')::boolean, false) then
    raise exception 'No store count is due: counts are taken when a supervisor asks, or at the end of the month';
  end if;
  if p_outlet_id is null
     or p_outlet_id not in (select outlet_id from public.outlets_for_user(auth.uid())) then
    raise exception 'That store is not one of yours';
  end if;

  -- A. In the store, now.
  select o.lat, o.lng, o.geofence_radius_m into store from public.outlets o where o.id = p_outlet_id;
  if p_lat is null or p_lng is null or p_accuracy_m is null or p_accuracy_m > 100 then
    raise exception 'Your location is not accurate enough. Step near a window and try again';
  end if;
  -- A store waiting for its location cannot say whether anyone is in it.
  if store.lat is null or store.lng is null then
    raise exception 'This store''s location is still being confirmed. Ask your supervisor, then count it once it is confirmed';
  end if;
  dist := public.distance_metres(p_lat, p_lng, store.lat, store.lng);
  if dist > store.geofence_radius_m + 25 then
    raise exception 'You must be in the store to submit its count (you are % m away)', round(dist::numeric);
  end if;
  if p_photo_path is null or not public.photo_is_fresh('reports', p_photo_path, 30) then
    raise exception 'Take the shelf photo in the app just before submitting';
  end if;
  if exists (select 1 from public.store_counts c
             where c.photo_path = p_photo_path
               and not (c.user_id = auth.uid() and c.outlet_id = p_outlet_id and c.count_date = today)) then
    raise exception 'That shelf photo has already been used';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Count at least one product';
  end if;
  if jsonb_array_length(p_lines) > 500 then
    raise exception 'Too many products in one count';
  end if;
  if exists (select 1 from jsonb_array_elements(p_lines) l
             where length(public.product_key(l->>'product_name')) not between 1 and 120) then
    raise exception 'Every product needs a name of up to 120 characters';
  end if;

  -- Every figure a line carries is a whole number from 0 up. A line has
  -- back store and shop floor (the sheet), or in_store (older phones).
  if exists (
    select 1 from jsonb_array_elements(p_lines) l,
         lateral (values ('back_store'), ('shop_floor'), ('in_store'), ('sold')) f(k)
    where l ? f.k and jsonb_typeof(l->f.k) <> 'null'
      and (jsonb_typeof(l->f.k) <> 'number'
           or (l->>f.k)::numeric <> trunc((l->>f.k)::numeric)
           or (l->>f.k)::numeric not between 0 and 1000000)
  ) or exists (
    select 1 from jsonb_array_elements(p_lines) l
    where coalesce(jsonb_typeof(l->'back_store'), 'null') = 'null'
      and coalesce(jsonb_typeof(l->'shop_floor'), 'null') = 'null'
      and coalesce(jsonb_typeof(l->'in_store'), 'null') = 'null'
  ) then
    raise exception 'Counts must be whole numbers from 0 up';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_lines) l
    where coalesce(jsonb_typeof(l->'expiry_date'), 'null') <> 'null'
      and (jsonb_typeof(l->'expiry_date') <> 'string'
           or l->>'expiry_date' !~ '^\d{4}-\d{2}-\d{2}$'
           or not (l->>'expiry_date' between '2000-01-01' and '2100-12-31'))
  ) then
    raise exception 'Expiry dates must be real dates';
  end if;
  if (select count(distinct public.product_key(l->>'product_name')) from jsonb_array_elements(p_lines) l)
     <> jsonb_array_length(p_lines) then
    raise exception 'A product appears twice in the count';
  end if;

  -- One shape from here on: in_store is the total in the store.
  select jsonb_agg(jsonb_build_object(
           'product_name', l->>'product_name',
           'back_store', b.back_store,
           'shop_floor', b.shop_floor,
           'in_store', case when b.back_store is null and b.shop_floor is null
                            then (l->>'in_store')::integer
                            else coalesce(b.back_store, 0) + coalesce(b.shop_floor, 0) end,
           'sold', coalesce((nullif(l->>'sold', ''))::integer, 0),
           'expiry_date', nullif(l->>'expiry_date', '')))
    into lines
  from jsonb_array_elements(p_lines) l,
       lateral (select (nullif(l->>'back_store', ''))::integer as back_store,
                       (nullif(l->>'shop_floor', ''))::integer as shop_floor) b;

  insert into public.products (name)
  select distinct on (public.product_key(l->>'product_name'))
         regexp_replace(btrim(l->>'product_name'), '\s+', ' ', 'g')
  from jsonb_array_elements(lines) l
  where not exists (select 1 from public.products p
                    where public.product_key(p.name) = public.product_key(l->>'product_name'))
  on conflict do nothing;

  insert into public.store_counts
    (user_id, outlet_id, product_id, count_date, in_store, sold, request_id,
     lat, lng, accuracy_m, distance_m, photo_path, back_store, shop_floor, expiry_date)
  select auth.uid(), p_outlet_id,
         (select p.id from public.products p
          where public.product_key(p.name) = public.product_key(l->>'product_name')
          order by p.created_at limit 1),
         today, (l->>'in_store')::integer, (l->>'sold')::integer, req,
         p_lat, p_lng, p_accuracy_m, dist, p_photo_path,
         (l->>'back_store')::integer, (l->>'shop_floor')::integer, (l->>'expiry_date')::date
  from jsonb_array_elements(lines) l
  on conflict (user_id, outlet_id, product_id, count_date)
  do update set in_store = excluded.in_store, sold = excluded.sold,
                back_store = excluded.back_store, shop_floor = excluded.shop_floor,
                expiry_date = excluded.expiry_date,
                request_id = excluded.request_id, lat = excluded.lat, lng = excluded.lng,
                accuracy_m = excluded.accuracy_m, distance_m = excluded.distance_m,
                photo_path = excluded.photo_path, updated_at = now();
  get diagnostics saved = row_count;

  -- B. Does it add up? (Flags, never refusals.)
  perform public.check_store_count(p_outlet_id, today);

  return saved;
end;
$_$;


--
-- Name: supervises_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supervises_user(target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles me
    join public.profiles them on them.id = target
    where me.id = auth.uid()
      and me.role = 'supervisor'
      and them.id <> me.id
      -- Field staff only, on every branch. Sharing an outlet with an admin
      -- or another supervisor has never meant supervising them, and the
      -- outlet branch used not to say so.
      and public.is_field_role(them.role)
      and (
        -- Reports to them, whatever stores are or are not involved.
        them.supervisor_id = me.id
        -- Or shares their outlet, which is how merchandisers are grouped.
        or (me.outlet_id is not null and them.outlet_id = me.outlet_id)
        or (me.outlet_id is not null
            and exists (select 1 from public.staff_outlets s
                        where s.user_id = them.id and s.outlet_id = me.outlet_id))
      )
  );
$$;


--
-- Name: support_assignees(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.support_assignees(p_thread uuid) RETURNS TABLE(user_id uuid, full_name text, role public.user_role)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  owner uuid;
begin
  select t.user_id into owner from public.support_threads t where t.id = p_thread;
  if owner is null then raise exception 'No such thread'; end if;
  if not (public.is_admin() or public.supervises_user(owner)) then
    raise exception 'That thread is not yours';
  end if;
  return query
    select w.user_id, w.full_name, w.role
    from public.alert_watchers(owner) w
    order by (w.user_id = auth.uid()) desc, w.full_name;
end;
$$;


--
-- Name: text_has_words(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.text_has_words(p_text text, p_min_length integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select length(btrim(coalesce(p_text, ''))) >= p_min_length
     and length(regexp_replace(coalesce(p_text, ''), '[^[:alpha:]]', '', 'g')) >= least(p_min_length, 2)
     and regexp_replace(coalesce(p_text, ''), '\s', '', 'g') !~ '(.)\1{5,}';
$$;


--
-- Name: text_is_clean(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.text_is_clean(p_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_text is null or (
    p_text !~ '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f]'
    and p_text !~* '(https?://|www\.|\m[a-z0-9-]{2,}\.(com|net|org|ng|io|co|xyz|info|biz|me|link|click|top|site|online|shop|app|ru|cn)\M)'
  );
$$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: tracking_coverage(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tracking_coverage(p_user uuid, p_date date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with bounds as (
    select
      min(a.created_at) filter (where a.type = 'opening') as opened_at,
      min(a.created_at) filter (where a.type = 'closing') as closed_at
    from public.attendance a
    where a.user_id = p_user and a.attendance_date = p_date
  ),
  window_secs as (
    select
      opened_at,
      closed_at,
      case
        when opened_at is null then 0
        else greatest(0, extract(epoch from (coalesce(closed_at, now()) - opened_at)))
      end as shift_secs
    from bounds
  ),
  pings as (
    select p.created_at, least(coalesce(p.gap_seconds, 360), 360) as covered
    from public.location_pings p, window_secs w
    where p.user_id = p_user
      and w.opened_at is not null
      and p.created_at >= w.opened_at
      and p.created_at <= coalesce(w.closed_at, now())
  )
  select jsonb_build_object(
    'date',            p_date,
    'shift_seconds',   (select round(shift_secs) from window_secs),
    'tracked_seconds', coalesce((select round(sum(covered)) from pings), 0),
    'ping_count',      (select count(*) from pings),
    'longest_gap_seconds', coalesce((select max(covered) from pings), 0),
    'last_ping_at',    (select max(created_at) from pings),
    'coverage_pct',    case
                         when (select shift_secs from window_secs) < 1 then null
                         else least(100, round(
                           100.0 * coalesce((select sum(covered) from pings), 0)
                           / (select shift_secs from window_secs)
                         ))
                       end
  )
  where p_user = auth.uid() or public.is_admin() or public.supervises_user(p_user);
$$;


--
-- Name: visit_place_due(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.visit_place_due() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.outlet_id is null then
    perform public.raise_place_due(new.user_id, new.arrived_lat, new.arrived_lng, new.arrived_accuracy_m,
                                   'visit', new.id, new.device_info->'position');
  end if;
  return null;
end;
$$;


--
-- Name: write_audit(text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_audit(p_action text, p_target_table text DEFAULT NULL::text, p_target_id uuid DEFAULT NULL::uuid, p_meta jsonb DEFAULT '{}'::jsonb, p_context jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  new_id uuid;
  c record;
begin
  if not (public.is_admin() or exists (select 1 from public.profiles
                                       where id = auth.uid() and role = 'supervisor' and is_active)) then
    raise exception 'Admins and supervisors only';
  end if;
  select * into c from public.audit_context_columns(p_context);
  insert into public.audit_log (actor_id, action, target_table, target_id, meta,
                                ip, user_agent, device, lat, lng, accuracy_m, location_source, place, country, vpn)
  values (auth.uid(), p_action, p_target_table, p_target_id, coalesce(p_meta, '{}'::jsonb),
          c.ip, c.user_agent, c.device, c.lat, c.lng, c.accuracy_m, c.location_source, c.place, c.country, c.vpn)
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: xm_acknowledge_expiry(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_acknowledge_expiry(p_alert uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.xm_require_admin();
  update public.xm_expiry_alerts
  set acknowledged_at = now(), acknowledged_by = auth.uid(), note = nullif(btrim(coalesce(p_note, '')), '')
  where id = p_alert and acknowledged_at is null;
  if not found then raise exception 'That alert does not exist or is already handled'; end if;
end;
$$;


--
-- Name: xm_can_submit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_can_submit() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select is_active and role in ('merchandiser'::user_role, 'marketer'::user_role,
                                   'admin'::user_role)
     from public.profiles where id = auth.uid()),
    false);
$$;


--
-- Name: xm_check_field_submission(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_check_field_submission(p_outlet uuid, p_captured_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.xm_can_submit() then
    raise exception 'You cannot submit stock or sales';
  end if;
  if not exists (select 1 from public.xm_stores where outlet_id = p_outlet and is_active) then
    raise exception 'That store is not in X Metrics yet. Ask your supervisor';
  end if;
  if p_outlet not in (select outlet_id from public.outlets_for_user(auth.uid())) then
    raise exception 'That store is not one of yours';
  end if;
  -- Kept on the phone while offline, but not for days.
  if p_captured_at is null or p_captured_at > now() + interval '2 minutes'
     or p_captured_at < now() - interval '72 hours' then
    raise exception 'Invalid capture time: it must be within the last 3 days';
  end if;
end;
$$;


--
-- Name: xm_claim_expiry_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_claim_expiry_alerts() RETURNS TABLE(id uuid, outlet_name text, product_name text, batch text, expiry_date date, days_left integer, units_on_hand integer, consider_pulling boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with told as (
    update public.xm_expiry_alerts a set notified_at = now()
    where a.notified_at is null and a.acknowledged_at is null
    returning a.*
  )
  select t.id, o.name, p.name, t.batch, t.expiry_date, t.days_left, t.units_on_hand, t.consider_pulling
  from told t join public.outlets o on o.id = t.outlet_id join public.products p on p.id = t.product_id
  order by t.days_left;
$$;


--
-- Name: xm_create_supply_import(text, text, text, text, text, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_create_supply_import(p_file_name text, p_kind text, p_read_by text, p_supplier text, p_invoice_no text, p_invoice_date date, p_rows integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare new_id uuid;
begin
  perform public.xm_require_admin();
  insert into public.xm_supply_imports
    (file_name, file_kind, read_by, supplier, invoice_no, invoice_date, rows_found, created_by)
  values (left(btrim(p_file_name), 200), p_kind, p_read_by, left(nullif(btrim(coalesce(p_supplier, '')), ''), 200),
          left(nullif(btrim(coalesce(p_invoice_no, '')), ''), 100), p_invoice_date, greatest(coalesce(p_rows, 0), 0),
          auth.uid())
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: xm_daily_velocity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_daily_velocity(p_outlet uuid, p_product uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(v.units), 0)::numeric / (select velocity_days from public.xm_settings)
  from public.xm_live_sale_lines v
  where v.outlet_id = p_outlet and v.product_id = p_product
    and v.sale_date > public.business_date() - (select velocity_days from public.xm_settings)
    and v.sale_date <= public.business_date();
$$;


--
-- Name: xm_expiry_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_expiry_scan() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  settings public.xm_settings;
  b record;
  left_days integer;
  win integer;
  vel numeric;
  to_sell numeric;
  added integer := 0;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin can run the expiry check';
  end if;
  select * into settings from public.xm_settings;

  for b in select * from public.xm_stock_on_hand where expiry_date is not null and units > 0 loop
    left_days := b.expiry_date - public.business_date();
    if left_days < 0 then
      win := 0;
    else
      select min(w) into win from unnest(settings.alert_windows_days) w where left_days <= w;
    end if;
    continue when win is null;

    vel := public.xm_daily_velocity(b.outlet_id, b.product_id);
    to_sell := case when vel > 0 then round(b.units / vel, 1) end;

    insert into public.xm_expiry_alerts
      (outlet_id, product_id, batch, expiry_date, window_days, days_left, units_on_hand,
       daily_velocity, days_to_sell, consider_pulling, count_id)
    values
      (b.outlet_id, b.product_id, b.batch, b.expiry_date, win, left_days, b.units,
       round(vel, 3), to_sell, (to_sell is null or to_sell > greatest(left_days, 0)), b.count_id)
    on conflict (outlet_id, product_id, batch, expiry_date, window_days) do nothing;
    if found then added := added + 1; end if;
  end loop;
  return added;
end;
$$;


--
-- Name: xm_finalise_month(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_finalise_month(p_month date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare kept integer;
begin
  perform public.xm_require_admin();
  if (date_trunc('month', p_month) + interval '1 month')::date > public.business_date() then
    raise exception 'A month can be finalised once it has ended';
  end if;
  insert into public.xm_monthly_grades (month, user_id, grade, score, band, finalised_by)
  select date_trunc('month', p_month)::date, (g->>'user_id')::uuid, g,
         (g->>'score')::numeric, g->>'band', auth.uid()
  from public.xm_month_grades(p_month) g
  on conflict (month, user_id) do nothing;
  get diagnostics kept = row_count;
  return kept;
end;
$$;


--
-- Name: xm_grade(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_grade(p_user uuid, p_month date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  settings public.xm_settings;
  m_start date := date_trunc('month', p_month)::date;
  m_end date := (date_trunc('month', p_month) + interval '1 month')::date - 1;
  last_day date;
  sold integer; target integer; target_kind text;
  store_sold integer;
  recs integer; recs_ok integer;
  present integer; sales_ok integer; counts_ok integer;
  lines integer; dated integer; expired_on_shelf integer;
  c_sales numeric; c_acc numeric; c_cons numeric; c_exp numeric;
  weight_sum numeric; score numeric; band text;
begin
  if auth.uid() is not null and auth.uid() <> p_user
     and not (public.is_admin() or public.supervises_user(p_user)) then
    raise exception 'You can only see grades for your own team';
  end if;
  select * into settings from public.xm_settings;
  last_day := least(m_end, public.business_date() - 1);

  -- Sales against target.
  select coalesce(sum(units), 0)::integer into sold from public.xm_live_sale_lines
  where user_id = p_user and sale_date between m_start and m_end;
  select target_units into target from public.xm_current_targets
  where month = m_start and user_id = p_user;
  if target is not null then
    target_kind := 'person';
    c_sales := least(100, round(100.0 * sold / target, 1));
  else
    select sum(t.target_units)::integer into target from public.xm_current_targets t
    where t.month = m_start and t.outlet_id in (select outlet_id from public.outlets_for_user(p_user));
    if target is not null then
      target_kind := 'store';
      select coalesce(sum(units), 0)::integer into store_sold from public.xm_live_sale_lines
      where sale_date between m_start and m_end
        and outlet_id in (select t.outlet_id from public.xm_current_targets t
                          where t.month = m_start
                            and t.outlet_id in (select outlet_id from public.outlets_for_user(p_user)));
      c_sales := least(100, round(100.0 * store_sold / target, 1));
    end if;
  end if;

  -- Stock accuracy.
  select count(*), count(*) filter (where not r.flagged) into recs, recs_ok
  from public.xm_reconciliations r join public.xm_counts c on c.id = r.count_id
  where c.user_id = p_user and c.voided_at is null and c.count_date between m_start and m_end;
  if recs > 0 then c_acc := round(100.0 * recs_ok / recs, 1); end if;

  -- Reporting consistency, against the days they clocked in.
  with days as (
    select distinct a.attendance_date as d from public.attendance a
    where a.user_id = p_user and a.type = 'opening'
      and a.attendance_date between m_start and last_day
  )
  select count(*),
         count(*) filter (where exists (
           select 1 from public.xm_sales s
           where s.user_id = p_user and s.sale_date = days.d and s.voided_at is null
             and s.captured_at <= ((days.d + 1)::timestamp at time zone 'Africa/Lagos')
                                 + make_interval(hours => settings.sales_grace_hours))),
         count(*) filter (where exists (
           select 1 from public.xm_counts c
           where c.user_id = p_user and c.voided_at is null
             and c.count_date between days.d - (settings.count_interval_days - 1) and days.d))
    into present, sales_ok, counts_ok
  from days;
  if present > 0 then c_cons := round(100.0 * (sales_ok + counts_ok) / (2 * present), 1); end if;

  -- Expiry handling.
  select count(*), count(l.expiry_date),
         count(*) filter (where l.expiry_date is not null and l.expiry_date < c.count_date and l.on_shelf > 0)
    into lines, dated, expired_on_shelf
  from public.xm_count_lines l join public.xm_counts c on c.id = l.count_id
  where c.user_id = p_user and c.voided_at is null and c.count_date between m_start and m_end;
  if lines > 0 then
    c_exp := round(50.0 * dated / lines + 50.0 * (1 - expired_on_shelf::numeric / lines), 1);
  end if;

  weight_sum := (case when c_sales is not null then settings.weight_sales else 0 end)
              + (case when c_acc is not null then settings.weight_accuracy else 0 end)
              + (case when c_cons is not null then settings.weight_consistency else 0 end)
              + (case when c_exp is not null then settings.weight_expiry else 0 end);
  if weight_sum > 0 then
    score := round((coalesce(c_sales * settings.weight_sales, 0)
                  + coalesce(c_acc * settings.weight_accuracy, 0)
                  + coalesce(c_cons * settings.weight_consistency, 0)
                  + coalesce(c_exp * settings.weight_expiry, 0)) / weight_sum, 1);
    band := case when score < settings.band_poor_below then 'Poor'
                 when score < settings.band_strong_from then 'Average'
                 else 'Strong' end;
  end if;

  return jsonb_build_object(
    'month', m_start, 'user_id', p_user, 'score', score, 'band', band,
    'weights', jsonb_build_object('sales', settings.weight_sales, 'accuracy', settings.weight_accuracy,
                                  'consistency', settings.weight_consistency, 'expiry', settings.weight_expiry),
    'bands', jsonb_build_object('poor_below', settings.band_poor_below, 'strong_from', settings.band_strong_from),
    'sales', jsonb_build_object('score', c_sales, 'units_sold', sold, 'target', target,
                                'target_kind', target_kind, 'store_units_sold', store_sold),
    'accuracy', jsonb_build_object('score', c_acc, 'reconciliations', recs, 'within_tolerance', recs_ok,
                                   'tolerance_pct', settings.tolerance_pct),
    'consistency', jsonb_build_object('score', c_cons, 'days_present', present,
                                      'sales_on_time', sales_ok, 'counts_in_time', counts_ok),
    'expiry', jsonb_build_object('score', c_exp, 'lines_counted', lines, 'expiry_recorded', dated,
                                 'expired_on_shelf', expired_on_shelf));
end;
$$;


--
-- Name: xm_log_supply(uuid, uuid, integer, text, date, date, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_log_supply(p_outlet uuid, p_product uuid, p_quantity integer, p_batch text, p_expiry date, p_supplied_on date, p_note text, p_cartons integer DEFAULT NULL::integer, p_units_per_carton integer DEFAULT NULL::integer, p_import uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  new_id uuid;
  prod record;
  per integer;
  units integer;
begin
  perform public.xm_require_admin();
  if not exists (select 1 from public.xm_stores where outlet_id = p_outlet and is_active) then
    raise exception 'Add the store to X Metrics first';
  end if;
  select id, name, units_per_carton into prod from public.products where id = p_product and is_active;
  if prod.id is null then
    raise exception 'That product does not exist or is retired';
  end if;
  if p_supplied_on is null or p_supplied_on > public.business_date() then
    raise exception 'The supply date cannot be in the future';
  end if;
  if p_expiry is not null and p_expiry < p_supplied_on then
    raise exception 'The expiry date is before the supply date';
  end if;

  if p_cartons is not null then
    if p_cartons < 1 or p_cartons > 100000 then
      raise exception 'Cartons must be a whole number from 1';
    end if;
    per := coalesce(p_units_per_carton, prod.units_per_carton);
    if per is null then
      raise exception 'Say how many units are in a carton of %', prod.name;
    end if;
    if per < 1 or per > 100000 then
      raise exception 'Units per carton must be a whole number from 1';
    end if;
    units := p_cartons * per;
    if prod.units_per_carton is null then
      update public.products set units_per_carton = per where id = prod.id;
    end if;
  else
    units := p_quantity;
  end if;
  if units is null or units < 1 or units > 1000000 then
    raise exception 'The quantity must be between 1 and 1,000,000 units';
  end if;

  insert into public.xm_supplies
    (outlet_id, product_id, quantity, batch, expiry_date, supplied_on, note, logged_by,
     cartons, units_per_carton, import_id)
  values (p_outlet, p_product, units, btrim(coalesce(p_batch, '')), p_expiry, p_supplied_on,
          nullif(btrim(coalesce(p_note, '')), ''), auth.uid(),
          p_cartons, case when p_cartons is not null then per end, p_import)
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: xm_log_supply_import(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_log_supply_import(p_import uuid, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r jsonb;
  i integer := 0;
begin
  perform public.xm_require_admin();
  if not exists (select 1 from public.xm_supply_imports where id = p_import) then
    raise exception 'That import does not exist';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'Choose at least one line to log';
  end if;
  if jsonb_array_length(p_rows) > 500 then
    raise exception 'Log at most 500 lines at a time';
  end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    i := i + 1;
    begin
      perform public.xm_log_supply(
        (r->>'outlet_id')::uuid, (r->>'product_id')::uuid,
        nullif(r->>'quantity', '')::integer, r->>'batch',
        nullif(r->>'expiry_date', '')::date, (r->>'supplied_on')::date, r->>'note',
        nullif(r->>'cartons', '')::integer, nullif(r->>'units_per_carton', '')::integer, p_import);
    exception when others then
      raise exception 'Line %: %', i, sqlerrm;
    end;
  end loop;
  update public.xm_supply_imports set rows_logged = rows_logged + i where id = p_import;
  return i;
end;
$$;


--
-- Name: xm_mark_policy_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_mark_policy_read(p_policy uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  if not exists (select 1 from public.xm_policy_versions where id = p_policy) then
    raise exception 'That policy does not exist';
  end if;
  insert into public.xm_policy_reads (policy_id, user_id) values (p_policy, auth.uid())
  on conflict do nothing;
end;
$$;


--
-- Name: xm_month_grades(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_month_grades(p_month date) RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.xm_grade(p.id, p_month) || jsonb_build_object('full_name', p.full_name)
  from public.profiles p
  where public.is_field_role(p.role)
    and (public.is_admin() or public.supervises_user(p.id))
    and (exists (select 1 from public.attendance a where a.user_id = p.id
                 and a.attendance_date between date_trunc('month', p_month)::date
                                           and (date_trunc('month', p_month) + interval '1 month')::date - 1)
         or exists (select 1 from public.xm_counts c where c.user_id = p.id
                    and c.count_date between date_trunc('month', p_month)::date
                                         and (date_trunc('month', p_month) + interval '1 month')::date - 1)
         or exists (select 1 from public.xm_sales s where s.user_id = p.id
                    and s.sale_date between date_trunc('month', p_month)::date
                                        and (date_trunc('month', p_month) + interval '1 month')::date - 1))
  order by p.full_name;
$$;


--
-- Name: xm_my_store_batches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_my_store_batches() RETURNS TABLE(outlet_id uuid, product_id uuid, batch text, expiry_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select h.outlet_id, h.product_id, h.batch, h.expiry_date
  from public.xm_stock_on_hand h
  where h.units > 0
    and h.outlet_id in (select o.outlet_id from public.outlets_for_user(auth.uid()) o);
$$;


--
-- Name: xm_oversees_outlet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_oversees_outlet(p_outlet uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.is_admin() or exists (
    select 1 from public.profiles p
    where public.supervises_user(p.id)
      and p_outlet in (select outlet_id from public.outlets_for_user(p.id))
  );
$$;


--
-- Name: xm_publish_policy(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_publish_policy(p_title text, p_body text, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare new_id uuid;
begin
  perform public.xm_require_admin();
  insert into public.xm_policy_versions (title, body, change_note, published_by)
  values (btrim(p_title), btrim(p_body), nullif(btrim(coalesce(p_note, '')), ''), auth.uid())
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: xm_reconcile_pending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_reconcile_pending() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  settings public.xm_settings;
  c record;
  p record;
  prev record;
  supplied integer;
  sold integer;
  expected integer;
  pct numeric;
  flag uuid;
  done integer := 0;
begin
  if auth.uid() is not null and not public.is_admin() then
    raise exception 'Only an admin can run reconciliation';
  end if;
  select * into settings from public.xm_settings;

  for c in
    select * from public.xm_counts
    where reconciled_at is null and voided_at is null and count_date < public.business_date()
    order by count_date, created_at
    for update skip locked
  loop
    for p in
      select l.product_id, sum(l.on_shelf + l.in_backroom)::integer as actual
      from public.xm_count_lines l where l.count_id = c.id group by l.product_id
    loop
      select pc.id, pc.count_date, sum(pl.on_shelf + pl.in_backroom)::integer as units
        into prev
      from public.xm_counts pc
      join public.xm_count_lines pl on pl.count_id = pc.id and pl.product_id = p.product_id
      where pc.outlet_id = c.outlet_id and pc.voided_at is null and pc.id <> c.id
        and (pc.count_date < c.count_date or (pc.count_date = c.count_date and pc.created_at < c.created_at))
      group by pc.id, pc.count_date, pc.created_at
      order by pc.count_date desc, pc.created_at desc
      limit 1;

      -- No earlier count of this product: this one is its baseline.
      continue when prev.id is null;

      select coalesce(sum(s.quantity), 0)::integer into supplied
      from public.xm_supplies s
      where s.outlet_id = c.outlet_id and s.product_id = p.product_id and s.voided_at is null
        and s.supplied_on > prev.count_date and s.supplied_on <= c.count_date;

      select coalesce(sum(v.units), 0)::integer into sold
      from public.xm_live_sale_lines v
      where v.outlet_id = c.outlet_id and v.product_id = p.product_id
        and v.sale_date > prev.count_date and v.sale_date <= c.count_date;

      expected := prev.units + supplied - sold;
      pct := round(100.0 * abs(p.actual - expected) / greatest(abs(expected), p.actual, 1), 2);
      flag := null;

      if pct > settings.tolerance_pct then
        insert into public.integrity_flags (user_id, kind, severity, summary, detail, outlet_id, flag_date)
        values (c.user_id, 'stock_discrepancy',
                case when pct > 4 * settings.tolerance_pct then 'high' else 'medium' end,
                format('%s units of %s %s at %s: expected %s, counted %s',
                       abs(p.actual - expected),
                       (select name from public.products where id = p.product_id),
                       case when p.actual > expected then 'more than expected' else 'missing' end,
                       (select name from public.outlets where id = c.outlet_id),
                       expected, p.actual),
                jsonb_build_object('count_id', c.id, 'product_id', p.product_id,
                                   'previous_count_id', prev.id, 'previous_units', prev.units,
                                   'supplied', supplied, 'sold', sold,
                                   'expected', expected, 'actual', p.actual, 'variance_pct', pct),
                c.outlet_id, c.count_date)
        returning id into flag;
      end if;

      insert into public.xm_reconciliations
        (count_id, product_id, previous_count_id, previous_units, supplied_units, sold_units,
         expected_units, actual_units, variance_units, variance_pct, tolerance_pct, flagged, flag_id)
      values
        (c.id, p.product_id, prev.id, prev.units, supplied, sold, expected, p.actual,
         p.actual - expected, pct, settings.tolerance_pct, flag is not null, flag)
      on conflict (count_id, product_id) do nothing;
    end loop;

    update public.xm_counts set reconciled_at = now() where id = c.id;
    done := done + 1;
  end loop;
  return done;
end;
$$;


--
-- Name: xm_require_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_require_admin() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Only an admin can do that in X Metrics';
  end if;
end;
$$;


--
-- Name: xm_review_grade(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_review_grade(p_grade uuid, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.xm_require_admin();
  update public.xm_monthly_grades
  set review_note = nullif(btrim(coalesce(p_note, '')), ''), reviewed_by = auth.uid(), reviewed_at = now()
  where id = p_grade;
  if not found then raise exception 'That grade does not exist'; end if;
end;
$$;


--
-- Name: xm_set_store(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_set_store(p_outlet uuid, p_active boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.xm_require_admin();
  if not exists (select 1 from public.outlets where id = p_outlet) then
    raise exception 'That store does not exist';
  end if;
  insert into public.xm_stores (outlet_id, enrolled_by, is_active)
  values (p_outlet, auth.uid(), p_active)
  on conflict (outlet_id) do update set is_active = excluded.is_active;
end;
$$;


--
-- Name: xm_set_target(date, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_set_target(p_month date, p_user uuid, p_outlet uuid, p_units integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare new_id uuid;
begin
  perform public.xm_require_admin();
  if p_user is not null and not exists (
    select 1 from public.profiles where id = p_user and public.is_field_role(role)) then
    raise exception 'Targets are set for merchandisers and marketers';
  end if;
  insert into public.xm_targets (month, user_id, outlet_id, target_units, set_by)
  values (date_trunc('month', p_month)::date, p_user, p_outlet, p_units, auth.uid())
  returning id into new_id;
  return new_id;
end;
$$;


--
-- Name: xm_settings_keep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_settings_keep() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.updated_by := auth.uid();
  new.updated_at := now();
  insert into public.xm_settings_history (settings, changed_by) values (to_jsonb(old), auth.uid());
  return new;
end;
$$;


--
-- Name: xm_submit_count(uuid, jsonb, double precision, double precision, double precision, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_submit_count(p_outlet uuid, p_lines jsonb, p_lat double precision, p_lng double precision, p_accuracy_m double precision, p_photo_path text, p_captured_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  store record;
  dist double precision;
  new_id uuid;
begin
  perform public.xm_check_field_submission(p_outlet, p_captured_at);

  if p_lat is null or p_lng is null or p_accuracy_m is null or p_accuracy_m > 100 then
    raise exception 'Your location is not accurate enough. Step near a window and try again';
  end if;
  select lat, lng, geofence_radius_m into store from public.outlets where id = p_outlet;
  -- A store waiting for its location cannot say where it is (034): the
  -- count is kept, with no distance.
  if store.lat is not null then
    dist := public.distance_metres(p_lat, p_lng, store.lat, store.lng);
    if dist > store.geofence_radius_m + 25 then
      raise exception 'You must be in the store to count it (you are % m away)', round(dist::numeric);
    end if;
  end if;

  if p_photo_path is null or p_photo_path not like auth.uid()::text || '/%'
     or coalesce(public.photo_verdict(p_photo_path), 'none') not in ('pass', 'unchecked') then
    raise exception 'Take the shelf photo in the app before sending the count';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Count at least one product';
  end if;
  if jsonb_array_length(p_lines) > 500 then
    raise exception 'Too many lines in one count';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_lines) l
    where not exists (select 1 from public.products p
                      where p.id::text = l->>'product_id' and p.is_active)
       or jsonb_typeof(l->'on_shelf') <> 'number' or jsonb_typeof(l->'in_backroom') <> 'number'
       or (l->>'on_shelf')::numeric <> trunc((l->>'on_shelf')::numeric)
       or (l->>'in_backroom')::numeric <> trunc((l->>'in_backroom')::numeric)
       or (l->>'on_shelf')::numeric not between 0 and 1000000
       or (l->>'in_backroom')::numeric not between 0 and 1000000
       or length(coalesce(l->>'batch', '')) > 60
  ) then
    raise exception 'Every line needs a product, and whole numbers from 0 up';
  end if;
  if (select count(distinct (l->>'product_id') || '|' || lower(btrim(coalesce(l->>'batch', ''))))
      from jsonb_array_elements(p_lines) l) <> jsonb_array_length(p_lines) then
    raise exception 'A product and batch appears twice in the count';
  end if;

  insert into public.xm_counts
    (outlet_id, user_id, count_date, captured_at, lat, lng, accuracy_m, distance_m, photo_path, is_opening)
  values
    (p_outlet, auth.uid(), (p_captured_at at time zone 'Africa/Lagos')::date, p_captured_at,
     p_lat, p_lng, p_accuracy_m, dist, p_photo_path,
     not exists (select 1 from public.xm_counts c where c.outlet_id = p_outlet and c.voided_at is null))
  returning id into new_id;

  insert into public.xm_count_lines (count_id, product_id, batch, expiry_date, on_shelf, in_backroom)
  select new_id, (l->>'product_id')::uuid, btrim(coalesce(l->>'batch', '')),
         nullif(l->>'expiry_date', '')::date,
         (l->>'on_shelf')::integer, (l->>'in_backroom')::integer
  from jsonb_array_elements(p_lines) l;

  return new_id;
end;
$$;


--
-- Name: xm_submit_sales(uuid, date, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_submit_sales(p_outlet uuid, p_sale_date date, p_lines jsonb, p_photo_path text, p_captured_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  settings public.xm_settings;
  new_id uuid;
begin
  perform public.xm_check_field_submission(p_outlet, p_captured_at);
  select * into settings from public.xm_settings;

  if p_sale_date is null or p_sale_date > public.business_date()
     or p_sale_date < public.business_date() - 3 then
    raise exception 'Sales can be sent for today or the last 3 days';
  end if;
  if p_photo_path is not null and (p_photo_path not like auth.uid()::text || '/%'
     or coalesce(public.photo_verdict(p_photo_path), 'none') not in ('pass', 'unchecked')) then
    raise exception 'Take the photo in the app before sending';
  end if;
  if settings.sales_photo_required and p_photo_path is null then
    raise exception 'Take a photo of the shelf before sending the day''s sales';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Enter at least one product';
  end if;
  if jsonb_array_length(p_lines) > 500 then
    raise exception 'Too many products in one report';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_lines) l
    where not exists (select 1 from public.products p
                      where p.id::text = l->>'product_id' and p.is_active)
       or jsonb_typeof(l->'units') <> 'number'
       or (l->>'units')::numeric <> trunc((l->>'units')::numeric)
       or (l->>'units')::numeric not between 0 and 1000000
  ) then
    raise exception 'Every line needs a product and a whole number of units from 0 up';
  end if;
  if (select count(distinct l->>'product_id') from jsonb_array_elements(p_lines) l)
     <> jsonb_array_length(p_lines) then
    raise exception 'A product appears twice in the report';
  end if;

  insert into public.xm_sales (outlet_id, user_id, sale_date, captured_at, photo_path)
  values (p_outlet, auth.uid(), p_sale_date, p_captured_at, p_photo_path)
  returning id into new_id;

  insert into public.xm_sale_lines (sale_id, product_id, units)
  select new_id, (l->>'product_id')::uuid, (l->>'units')::integer
  from jsonb_array_elements(p_lines) l;

  update public.xm_sales set superseded_by = new_id
  where outlet_id = p_outlet and user_id = auth.uid() and sale_date = p_sale_date
    and id <> new_id and superseded_by is null and voided_at is null;

  return new_id;
end;
$$;


--
-- Name: xm_void(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.xm_void(p_kind text, p_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare reason text := btrim(coalesce(p_reason, ''));
begin
  perform public.xm_require_admin();
  if length(reason) < 3 then
    raise exception 'Say why it is being voided';
  end if;
  if p_kind = 'supply' then
    update public.xm_supplies set voided_at = now(), voided_by = auth.uid(), void_reason = reason
    where id = p_id and voided_at is null;
  elsif p_kind = 'count' then
    update public.xm_counts set voided_at = now(), voided_by = auth.uid(), void_reason = reason
    where id = p_id and voided_at is null;
  elsif p_kind = 'sales' then
    update public.xm_sales set voided_at = now(), voided_by = auth.uid(), void_reason = reason
    where id = p_id and voided_at is null;
  else
    raise exception 'Unknown record';
  end if;
  if not found then
    raise exception 'That record does not exist or is already voided';
  end if;
end;
$$;


--
-- Name: attendance; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attendance (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid DEFAULT auth.uid() NOT NULL,
    outlet_id uuid,
    outlet_lat double precision,
    outlet_lng double precision,
    outlet_radius_m integer,
    type public.attendance_type NOT NULL,
    lat double precision NOT NULL,
    lng double precision NOT NULL,
    accuracy_m double precision NOT NULL,
    address text,
    selfie_path text,
    thumb_path text,
    distance_m double precision,
    status public.attendance_status,
    device_info jsonb DEFAULT '{}'::jsonb NOT NULL,
    client_captured_at timestamp with time zone NOT NULL,
    attendance_date date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    place_name text,
    place_source text,
    time_verdict text,
    time_detail jsonb,
    CONSTRAINT attendance_time_verdict_check CHECK (((time_verdict IS NULL) OR (time_verdict = ANY (ARRAY['live'::text, 'offline_confirmed'::text, 'offline_unproven'::text, 'network_was_available'::text, 'phone_clock_wrong'::text, 'backdated'::text]))))
);


--
-- Name: COLUMN attendance.place_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attendance.place_name IS 'Business or landmark at the captured coordinates, when one was identified.';


--
-- Name: COLUMN attendance.place_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attendance.place_source IS 'outlet | google | osm | coordinates — where place_name and address came from.';


--
-- Name: location_alerts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.location_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    attendance_id uuid,
    alert_type public.alert_type NOT NULL,
    distance_m double precision,
    is_resolved boolean DEFAULT false NOT NULL,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: alert_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.alert_detail WITH (security_invoker='true') AS
 SELECT l.id,
    l.user_id,
    p.full_name AS staff_name,
    p.phone AS staff_phone,
    o.name AS outlet_name,
    l.alert_type,
    l.distance_m,
    l.is_resolved,
    l.note,
    l.created_at,
    l.resolved_at,
    r.full_name AS resolved_by_name,
    l.attendance_id,
    a.place_name,
    a.address,
    a.lat,
    a.lng,
    COALESCE(NULLIF(TRIM(BOTH ', '::text FROM concat_ws(', '::text, a.place_name, NULLIF(a.address, a.place_name))), ''::text), a.address,
        CASE
            WHEN (a.lat IS NOT NULL) THEN ((round((a.lat)::numeric, 5) || ', '::text) || round((a.lng)::numeric, 5))
            ELSE NULL::text
        END) AS location_label
   FROM ((((public.location_alerts l
     JOIN public.profiles p ON ((p.id = l.user_id)))
     LEFT JOIN public.outlets o ON ((o.id = p.outlet_id)))
     LEFT JOIN public.profiles r ON ((r.id = l.resolved_by)))
     LEFT JOIN public.attendance a ON ((a.id = l.attendance_id)));


--
-- Name: app_installs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_installs (
    user_id uuid NOT NULL,
    platform text NOT NULL,
    app_version text,
    app_build integer,
    web_build text,
    last_seen timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT app_installs_app_build_check CHECK (((app_build IS NULL) OR (app_build >= 0))),
    CONSTRAINT app_installs_app_version_check CHECK (((app_version IS NULL) OR (length(app_version) <= 40))),
    CONSTRAINT app_installs_platform_check CHECK ((platform = ANY (ARRAY['android'::text, 'ios'::text, 'web'::text]))),
    CONSTRAINT app_installs_web_build_check CHECK (((web_build IS NULL) OR (length(web_build) <= 80)))
);


--
-- Name: app_releases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.app_releases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    audience text DEFAULT 'everyone'::text NOT NULL,
    required boolean DEFAULT false NOT NULL,
    min_android_build integer,
    min_ios_build integer,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    withdrawn_at timestamp with time zone,
    CONSTRAINT app_releases_audience_check CHECK ((audience = ANY (ARRAY['everyone'::text, 'field'::text, 'office'::text]))),
    CONSTRAINT app_releases_min_android_build_check CHECK (((min_android_build IS NULL) OR (min_android_build > 0))),
    CONSTRAINT app_releases_min_ios_build_check CHECK (((min_ios_build IS NULL) OR (min_ios_build > 0))),
    CONSTRAINT app_releases_notes_check CHECK ((length(notes) <= 3000)),
    CONSTRAINT app_releases_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 120)))
);


--
-- Name: app_minimum_builds; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.app_minimum_builds WITH (security_invoker='true') AS
 SELECT max(min_android_build) AS android,
    max(min_ios_build) AS ios
   FROM public.app_releases
  WHERE (withdrawn_at IS NULL);


--
-- Name: assistant_conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assistant_conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid DEFAULT auth.uid() NOT NULL,
    title text DEFAULT 'New conversation'::text NOT NULL,
    turns jsonb DEFAULT '[]'::jsonb NOT NULL,
    turn_count integer GENERATED ALWAYS AS (jsonb_array_length(turns)) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT assistant_conversations_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 120))),
    CONSTRAINT assistant_conversations_turns_check CHECK (((jsonb_typeof(turns) = 'array'::text) AND (octet_length((turns)::text) <= 1500000)))
);


--
-- Name: attendance_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.attendance_detail WITH (security_invoker='true') AS
 SELECT a.id,
    a.user_id,
    p.full_name AS staff_name,
    p.phone AS staff_phone,
    a.attendance_date,
    a.type,
    a.created_at,
    to_char((a.created_at AT TIME ZONE 'Africa/Lagos'::text), 'YYYY-MM-DD HH24:MI'::text) AS local_time,
    a.outlet_id,
    o.name AS outlet_name,
    o.shift_start,
    o.shift_end,
    a.address,
    a.place_name,
    a.place_source,
    COALESCE(NULLIF(TRIM(BOTH ', '::text FROM concat_ws(', '::text, a.place_name, NULLIF(a.address, a.place_name))), ''::text), a.address, ((round((a.lat)::numeric, 5) || ', '::text) || round((a.lng)::numeric, 5))) AS location_label,
    a.lat,
    a.lng,
    a.accuracy_m,
    a.distance_m,
    a.outlet_lat,
    a.outlet_lng,
    a.outlet_radius_m,
    a.status,
    a.selfie_path,
    a.thumb_path,
    a.device_info,
    a.client_captured_at,
        CASE
            WHEN ((a.type = 'opening'::public.attendance_type) AND (o.shift_start IS NOT NULL) AND (((a.created_at AT TIME ZONE 'Africa/Lagos'::text))::time without time zone > o.shift_start)) THEN true
            ELSE false
        END AS is_late
   FROM ((public.attendance a
     JOIN public.profiles p ON ((p.id = a.user_id)))
     LEFT JOIN public.outlets o ON ((o.id = a.outlet_id)));


--
-- Name: audit_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid,
    action text NOT NULL,
    target_table text,
    target_id uuid,
    meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    ip text,
    user_agent text,
    device jsonb,
    lat double precision,
    lng double precision,
    accuracy_m double precision,
    location_source text,
    place text,
    country text,
    vpn boolean,
    CONSTRAINT audit_log_accuracy_m_check CHECK (((accuracy_m IS NULL) OR (accuracy_m >= (0)::double precision))),
    CONSTRAINT audit_log_country_check CHECK (((country IS NULL) OR (length(country) <= 8))),
    CONSTRAINT audit_log_ip_check CHECK (((ip IS NULL) OR (length(ip) <= 64))),
    CONSTRAINT audit_log_lat_check CHECK (((lat IS NULL) OR ((lat >= ('-90'::integer)::double precision) AND (lat <= (90)::double precision)))),
    CONSTRAINT audit_log_lng_check CHECK (((lng IS NULL) OR ((lng >= ('-180'::integer)::double precision) AND (lng <= (180)::double precision)))),
    CONSTRAINT audit_log_location_source_check CHECK (((location_source IS NULL) OR (location_source = ANY (ARRAY['browser'::text, 'ip'::text])))),
    CONSTRAINT audit_log_place_check CHECK (((place IS NULL) OR (length(place) <= 200))),
    CONSTRAINT audit_log_user_agent_check CHECK (((user_agent IS NULL) OR (length(user_agent) <= 500)))
);


--
-- Name: audit_log_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.audit_log_detail WITH (security_invoker='true') AS
 SELECT a.id,
    a.actor_id,
    a.action,
    a.target_table,
    a.target_id,
    a.meta,
    a.created_at,
    a.ip,
    a.user_agent,
    a.device,
    a.lat,
    a.lng,
    a.accuracy_m,
    a.location_source,
    a.place,
    a.country,
    a.vpn,
    p.full_name AS actor_name,
    (p.role)::text AS actor_role
   FROM (public.audit_log a
     LEFT JOIN public.profiles p ON ((p.id = a.actor_id)));


