    CONSTRAINT store_counts_back_store_check CHECK (((back_store IS NULL) OR ((back_store >= 0) AND (back_store <= 1000000)))),
    CONSTRAINT store_counts_expiry_date_check CHECK (((expiry_date IS NULL) OR ((expiry_date >= '2000-01-01'::date) AND (expiry_date <= '2100-12-31'::date)))),
    CONSTRAINT store_counts_in_store_check CHECK (((in_store >= 0) AND (in_store <= 1000000))),
    CONSTRAINT store_counts_shop_floor_check CHECK (((shop_floor IS NULL) OR ((shop_floor >= 0) AND (shop_floor <= 1000000)))),
    CONSTRAINT store_counts_sold_check CHECK (((sold >= 0) AND (sold <= 1000000)))
);


--
-- Name: count_request_progress; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.count_request_progress WITH (security_invoker='true') AS
 SELECT r.id,
    r.requested_by,
    p.full_name AS requested_by_name,
    r.due_date,
    r.note,
    r.created_at,
    r.closed_at,
    ((r.closed_at IS NULL) AND (r.due_date >= public.business_date())) AS is_open,
    ( SELECT count(*) AS count
           FROM public.count_request_targets t
          WHERE (t.request_id = r.id)) AS people,
    ( SELECT count(DISTINCT x.user_id) AS count
           FROM ( SELECT c.user_id
                   FROM public.store_counts c
                  WHERE (c.request_id = r.id)
                UNION
                 SELECT s.user_id
                   FROM public.store_count_sheets s
                  WHERE (s.request_id = r.id)) x) AS counted,
    COALESCE(( SELECT array_agg(tp.full_name ORDER BY tp.full_name) AS array_agg
           FROM (public.count_request_targets t
             JOIN public.profiles tp ON ((tp.id = t.user_id)))
          WHERE ((t.request_id = r.id) AND (NOT (EXISTS ( SELECT 1
                   FROM public.store_counts c
                  WHERE ((c.request_id = r.id) AND (c.user_id = t.user_id))))) AND (NOT (EXISTS ( SELECT 1
                   FROM public.store_count_sheets s
                  WHERE ((s.request_id = r.id) AND (s.user_id = t.user_id))))))), '{}'::text[]) AS waiting_on
   FROM (public.count_requests r
     JOIN public.profiles p ON ((p.id = r.requested_by)));


