    CONSTRAINT device_beacons_battery_pct_check CHECK (((battery_pct >= 0) AND (battery_pct <= 100))),
    CONSTRAINT device_beacons_connection_check CHECK (((connection IS NULL) OR (length(connection) <= 20))),
    CONSTRAINT device_beacons_lat_check CHECK (((lat >= ('-90'::integer)::double precision) AND (lat <= (90)::double precision))),
    CONSTRAINT device_beacons_lng_check CHECK (((lng >= ('-180'::integer)::double precision) AND (lng <= (180)::double precision))),
    CONSTRAINT device_beacons_outbox_count_check CHECK ((outbox_count >= 0)),
    CONSTRAINT device_beacons_reason_check CHECK ((reason = ANY (ARRAY['open'::text, 'visible'::text, 'hidden'::text, 'online'::text, 'interval'::text])))
);


--
-- Name: excuse_checks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.excuse_checks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    claim text NOT NULL,
    window_from timestamp with time zone NOT NULL,
    window_to timestamp with time zone NOT NULL,
    verdict text NOT NULL,
    headline text NOT NULL,
    note text,
    checked_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT excuse_checks_check CHECK ((window_to > window_from)),
    CONSTRAINT excuse_checks_claim_check CHECK ((claim = ANY (ARRAY['no_network'::text, 'phone_off'::text, 'gps_failed'::text, 'at_store'::text, 'app_failed'::text]))),
    CONSTRAINT excuse_checks_headline_check CHECK (((length(headline) >= 1) AND (length(headline) <= 500))),
    CONSTRAINT excuse_checks_note_check CHECK (((note IS NULL) OR (length(note) <= 500))),
    CONSTRAINT excuse_checks_verdict_check CHECK ((verdict = ANY (ARRAY['false'::text, 'doubtful'::text, 'fits'::text, 'unknown'::text])))
);


--
-- Name: excuse_check_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.excuse_check_detail WITH (security_invoker='true') AS
 SELECT e.id,
    e.user_id,
    e.claim,
    e.window_from,
    e.window_to,
    e.verdict,
    e.headline,
    e.note,
    e.checked_by,
    e.created_at,
    p.full_name AS staff_name,
    c.full_name AS checked_by_name
   FROM ((public.excuse_checks e
     JOIN public.profiles p ON ((p.id = e.user_id)))
     LEFT JOIN public.profiles c ON ((c.id = e.checked_by)));


--
-- Name: integrity_flags; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integrity_flags (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    severity text DEFAULT 'medium'::text NOT NULL,
    summary text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    outlet_id uuid,
    flag_date date DEFAULT public.business_date() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_note text,
    notified_at timestamp with time zone,
    CONSTRAINT integrity_flags_kind_check CHECK ((kind = ANY (ARRAY['repeated_exact_location'::text, 'perfect_accuracy'::text, 'impossible_journey'::text, 'count_units_missing'::text, 'count_identical'::text, 'count_round_numbers'::text, 'photo_rejected'::text, 'photo_unchecked'::text, 'own_named_place'::text, 'selfie_at_home'::text, 'backdated_clock'::text, 'phone_clock_wrong'::text, 'late_sync_with_network'::text, 'vpn_suspected'::text, 'ip_location_mismatch'::text, 'timezone_mismatch'::text, 'gps_mock_fingerprint'::text, 'mock_location_confirmed'::text, 'device_integrity_failed'::text, 'late_clock_in'::text, 'early_clock_out'::text, 'stock_discrepancy'::text]))),
    CONSTRAINT integrity_flags_review_note_check CHECK (((review_note IS NULL) OR (length(review_note) <= 500))),
    CONSTRAINT integrity_flags_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text])))
);


--
-- Name: integrity_flag_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.integrity_flag_detail WITH (security_invoker='true') AS
 SELECT f.id,
    f.user_id,
    p.full_name AS staff_name,
    f.kind,
    f.severity,
    f.summary,
    f.detail,
    f.outlet_id,
    o.name AS outlet_name,
    f.flag_date,
    f.created_at,
    f.reviewed_at,
    r.full_name AS reviewed_by_name,
    f.review_note
   FROM (((public.integrity_flags f
     JOIN public.profiles p ON ((p.id = f.user_id)))
     LEFT JOIN public.outlets o ON ((o.id = f.outlet_id)))
     LEFT JOIN public.profiles r ON ((r.id = f.reviewed_by)));


