--
-- Name: known_places; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.known_places (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    address text,
    lat double precision NOT NULL,
    lng double precision NOT NULL,
    radius_m integer DEFAULT 50 NOT NULL,
    source text NOT NULL,
    verified boolean DEFAULT false NOT NULL,
    times_seen integer DEFAULT 1 NOT NULL,
    named_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    photo_path text,
    visitors uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    store_candidates uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    selfie_path text,
    position_evidence jsonb,
    CONSTRAINT known_places_address_check CHECK (((address IS NULL) OR (length(address) <= 400))),
    CONSTRAINT known_places_lat_check CHECK (((lat >= ('-90'::integer)::double precision) AND (lat <= (90)::double precision))),
    CONSTRAINT known_places_lng_check CHECK (((lng >= ('-180'::integer)::double precision) AND (lng <= (180)::double precision))),
    CONSTRAINT known_places_name_check CHECK (((length(btrim(name)) >= 2) AND (length(btrim(name)) <= 120))),
    CONSTRAINT known_places_radius_m_check CHECK (((radius_m >= 15) AND (radius_m <= 500))),
    CONSTRAINT known_places_source_check CHECK ((source = ANY (ARRAY['google'::text, 'osm'::text, 'staff'::text, 'admin'::text, 'clock_in'::text])))
);


--
-- Name: known_place_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.known_place_detail WITH (security_invoker='true') AS
 SELECT k.id,
    k.name,
    k.address,
    k.lat,
    k.lng,
    k.radius_m,
    k.source,
    k.verified,
    k.times_seen,
    k.created_at,
    k.last_seen_at,
    p.full_name AS named_by_name,
    k.named_by,
    k.photo_path,
    cardinality(k.visitors) AS visitor_count,
    ((k.source = 'staff'::text) AND (k.visitors = ARRAY[k.named_by])) AS only_namer_visits,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name) ORDER BY o.name) AS jsonb_agg
           FROM public.outlets o
          WHERE ((o.id = ANY (k.store_candidates)) AND (o.lat IS NULL))), '[]'::jsonb) AS candidate_stores,
    COALESCE(( SELECT jsonb_agg(v.full_name ORDER BY v.full_name) AS jsonb_agg
           FROM public.profiles v
          WHERE (v.id = ANY (k.visitors))), '[]'::jsonb) AS visitor_names,
    k.selfie_path
   FROM (public.known_places k
     LEFT JOIN public.profiles p ON ((p.id = k.named_by)));


