--

COMMENT ON COLUMN public.location_pings.gap_seconds IS 'Seconds since this user''s previous ping today. Large values mean the app was closed, backgrounded or the phone was locked. Null on the first ping.';


--
-- Name: COLUMN location_pings.place_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.location_pings.place_name IS 'Resolved only for pings that raised a geofence alert; null otherwise.';


