--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sender_id uuid,
    title text NOT NULL,
    body text NOT NULL,
    url text,
    audience public.notification_audience NOT NULL,
    audience_detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    recipients integer DEFAULT 0 NOT NULL,
    delivered integer DEFAULT 0 NOT NULL,
    failed integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT notifications_body_check CHECK (((length(TRIM(BOTH FROM body)) >= 1) AND (length(TRIM(BOTH FROM body)) <= 400))),
    CONSTRAINT notifications_title_check CHECK (((length(TRIM(BOTH FROM title)) >= 1) AND (length(TRIM(BOTH FROM title)) <= 80)))
);


--
-- Name: notification_log; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.notification_log WITH (security_invoker='true') AS
 SELECT id,
    sender_id,
    public.office_name(sender_id) AS sender_name,
    title,
    body,
    url,
    audience,
    audience_detail,
    recipients,
    delivered,
    failed,
    created_at,
        CASE
            WHEN ((audience_detail ->> 'kind'::text) ~~ 'support%'::text) THEN 'support'::text
            WHEN ((sender_id IS NULL) OR ((audience_detail ->> 'system'::text) = 'true'::text) OR (audience_detail ? 'kind'::text)) THEN 'alert'::text
            ELSE 'message'::text
        END AS kind,
    ( SELECT (count(*))::integer AS count
           FROM public.notification_deliveries d
          WHERE ((d.notification_id = n.id) AND (d.read_at IS NOT NULL))) AS read_count,
    ( SELECT (count(*))::integer AS count
           FROM public.notification_deliveries d
          WHERE ((d.notification_id = n.id) AND (d.status = 'no_device'::text))) AS no_device
   FROM public.notifications n;


