    named_at timestamp with time zone,
    place_id uuid,
    dismissed_at timestamp with time zone,
    dismissed_by uuid,
    dismiss_reason text,
    CONSTRAINT place_naming_due_dismiss_reason_check CHECK (((dismiss_reason IS NULL) OR ((length(btrim(dismiss_reason)) >= 3) AND (length(btrim(dismiss_reason)) <= 300)))),
    CONSTRAINT place_naming_due_source_kind_check CHECK ((source_kind = ANY (ARRAY['clock_in'::text, 'visit'::text])))
);


--
-- Name: place_naming_due_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.place_naming_due_detail WITH (security_invoker='true') AS
 SELECT d.id,
    d.user_id,
    d.lat,
    d.lng,
    d.accuracy_m,
    d.source_kind,
    d.source_id,
    d.due_date,
    d.created_at,
    d.named_at,
    d.place_id,
    d.dismissed_at,
    d.dismissed_by,
    d.dismiss_reason,
    p.full_name AS staff_name,
    k.name AS place_name,
    db.full_name AS dismissed_by_name
   FROM (((public.place_naming_due d
     JOIN public.profiles p ON ((p.id = d.user_id)))
     LEFT JOIN public.known_places k ON ((k.id = d.place_id)))
     LEFT JOIN public.profiles db ON ((db.id = d.dismissed_by)));


