--
-- Name: staff_allocation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.staff_allocation WITH (security_invoker='true') AS
 SELECT p.id AS user_id,
    p.full_name AS staff_name,
    p.role,
    p.is_active,
    p.outlet_id AS home_outlet_id,
    home.name AS home_outlet_name,
    COALESCE(( SELECT array_agg(o.name ORDER BY o.name) AS array_agg
           FROM (public.staff_outlets s
             JOIN public.outlets o ON ((o.id = s.outlet_id)))
          WHERE (s.user_id = p.id)), '{}'::text[]) AS outlet_names,
    COALESCE(( SELECT array_agg(s.outlet_id) AS array_agg
           FROM public.staff_outlets s
          WHERE (s.user_id = p.id)), '{}'::uuid[]) AS outlet_ids
   FROM (public.profiles p
     LEFT JOIN public.outlets home ON ((home.id = p.outlet_id)))
  WHERE public.is_field_role(p.role);


--
-- Name: staff_roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.staff_roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    base_role public.user_role NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    counts_stock boolean DEFAULT true NOT NULL,
    CONSTRAINT staff_roles_base_role_check CHECK ((base_role = ANY (ARRAY['merchandiser'::public.user_role, 'marketer'::public.user_role, 'supervisor'::public.user_role]))),
    CONSTRAINT staff_roles_name_check CHECK ((((length(btrim(name)) >= 2) AND (length(btrim(name)) <= 40)) AND (name ~ '^[[:alpha:]][[:alpha:][:space:]&/''-]*$'::text))),
    CONSTRAINT staff_roles_not_built_in CHECK ((lower(btrim(name)) <> ALL (ARRAY['merchandiser'::text, 'merchandisers'::text, 'marketer'::text, 'marketers'::text, 'supervisor'::text, 'supervisors'::text, 'admin'::text, 'admins'::text, 'administrator'::text])))
);


