);


--
-- Name: store_count_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.store_count_detail WITH (security_invoker='true') AS
 SELECT c.id,
    c.count_date,
    c.user_id,
    p.full_name AS staff_name,
    c.outlet_id,
    o.name AS outlet_name,
    c.product_id,
    pr.name AS product_name,
    pr.sku,
    c.in_store,
    c.sold,
    c.updated_at,
    c.distance_m,
    c.accuracy_m,
    c.photo_path,
    pr.barcode,
    c.back_store,
    c.shop_floor,
    c.expiry_date
   FROM (((public.store_counts c
     JOIN public.profiles p ON ((p.id = c.user_id)))
     JOIN public.outlets o ON ((o.id = c.outlet_id)))
     JOIN public.products pr ON ((pr.id = c.product_id)));


--
-- Name: store_count_sheet_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.store_count_sheet_detail WITH (security_invoker='true') AS
 SELECT s.id,
    s.user_id,
    p.full_name AS staff_name,
    s.outlet_id,
    o.name AS outlet_name,
    s.count_date,
    s.request_id,
    s.path,
    s.file_name,
    s.content_type,
    s.size_bytes,
    s.created_at
   FROM ((public.store_count_sheets s
     JOIN public.profiles p ON ((p.id = s.user_id)))
     JOIN public.outlets o ON ((o.id = s.outlet_id)));


--
-- Name: store_coverage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.store_coverage WITH (security_invoker='true') AS
 SELECT o.id AS outlet_id,
    o.name,
    o.address,
    o.lat,
    o.lng,
    o.is_active,
    ( SELECT (count(DISTINCT pr.id))::integer AS count
           FROM public.profiles pr
          WHERE (pr.is_active AND public.is_field_role(pr.role) AND ((pr.outlet_id = o.id) OR (EXISTS ( SELECT 1
                   FROM public.staff_outlets s
                  WHERE ((s.user_id = pr.id) AND (s.outlet_id = o.id))))))) AS staff_assigned,
    last.arrived_at AS last_visit_at,
    last.visit_date AS last_visit_date,
    last.user_id AS last_visit_user_id,
    last.full_name AS last_visit_by,
    ( SELECT (count(*))::integer AS count
           FROM public.store_visits v
          WHERE ((v.outlet_id = o.id) AND (v.visit_date >= (public.business_date() - 29)))) AS visits_30d
   FROM (public.outlets o
     LEFT JOIN LATERAL ( SELECT v.arrived_at,
            v.visit_date,
            v.user_id,
            p.full_name
           FROM (public.store_visits v
             JOIN public.profiles p ON ((p.id = v.user_id)))
          WHERE (v.outlet_id = o.id)
          ORDER BY v.arrived_at DESC
         LIMIT 1) last ON (true));


