-- Name: support_threads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.support_threads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    outlet_id uuid,
    subject text NOT NULL,
    status public.support_status DEFAULT 'open'::public.support_status NOT NULL,
    escalated_at timestamp with time zone,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_message_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_to uuid,
    assigned_at timestamp with time zone,
    CONSTRAINT support_threads_subject_check CHECK (((length(subject) >= 1) AND (length(subject) <= 160)))
);


--
-- Name: support_inbox; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.support_inbox WITH (security_invoker='true') AS
 SELECT t.id,
    t.user_id,
    p.full_name AS staff_name,
    p.role AS staff_role,
    t.subject,
    t.status,
    t.outlet_id,
    o.name AS outlet_name,
    t.created_at,
    t.last_message_at,
    t.escalated_at,
    t.resolved_at,
    public.office_name(t.resolved_by) AS resolved_by_name,
    t.assigned_to,
    public.office_name(t.assigned_to) AS assigned_name,
    t.assigned_at,
    s.message_count,
    s.last_body,
    s.last_sender,
    s.last_office_at,
    s.office_replies,
        CASE
            WHEN (t.status = ANY (ARRAY['open'::public.support_status, 'escalated'::public.support_status])) THEN COALESCE(w.first_unanswered_at, t.escalated_at, t.last_message_at)
            ELSE NULL::timestamp with time zone
        END AS waiting_since
   FROM ((((public.support_threads t
     JOIN public.profiles p ON ((p.id = t.user_id)))
     LEFT JOIN public.outlets o ON ((o.id = t.outlet_id)))
     CROSS JOIN LATERAL ( SELECT (count(*))::integer AS message_count,
            (array_agg(m.body ORDER BY m.created_at DESC))[1] AS last_body,
            (array_agg(m.sender_role ORDER BY m.created_at DESC))[1] AS last_sender,
            max(m.created_at) FILTER (WHERE (m.sender_role = ANY (ARRAY['admin'::public.support_sender, 'supervisor'::public.support_sender]))) AS last_office_at,
            (count(*) FILTER (WHERE (m.sender_role = ANY (ARRAY['admin'::public.support_sender, 'supervisor'::public.support_sender]))))::integer AS office_replies
           FROM public.support_messages m
          WHERE (m.thread_id = t.id)) s)
     CROSS JOIN LATERAL ( SELECT min(m.created_at) AS first_unanswered_at
           FROM public.support_messages m
          WHERE ((m.thread_id = t.id) AND (m.sender_role = 'staff'::public.support_sender) AND (m.created_at > COALESCE(s.last_office_at, '-infinity'::timestamp with time zone)))) w);


--
-- Name: support_quick_replies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.support_quick_replies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT support_quick_replies_body_check CHECK (((length(btrim(body)) >= 1) AND (length(btrim(body)) <= 1000))),
    CONSTRAINT support_quick_replies_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 60)))
);


--
-- Name: support_thread_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.support_thread_detail WITH (security_invoker='true') AS
 SELECT t.id,
    t.user_id,
    p.full_name AS staff_name,
    p.role AS staff_role,
    t.subject,
    t.status,
    t.outlet_id,
    o.name AS outlet_name,
    t.created_at,
    t.last_message_at,
    t.escalated_at,
    t.resolved_at,
    rb.full_name AS resolved_by_name,
    ( SELECT count(*) AS count
           FROM public.support_messages m
          WHERE (m.thread_id = t.id)) AS message_count,
    ( SELECT m.body
           FROM public.support_messages m
          WHERE (m.thread_id = t.id)
          ORDER BY m.created_at DESC
         LIMIT 1) AS last_body
   FROM (((public.support_threads t
     JOIN public.profiles p ON ((p.id = t.user_id)))
     LEFT JOIN public.outlets o ON ((o.id = t.outlet_id)))
     LEFT JOIN public.profiles rb ON ((rb.id = t.resolved_by)));


