    daily_velocity numeric(10,3) NOT NULL,
    days_to_sell numeric(10,1),
    consider_pulling boolean NOT NULL,
    count_id uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    notified_at timestamp with time zone,
    acknowledged_at timestamp with time zone,
    acknowledged_by uuid,
    note text,
    CONSTRAINT xm_expiry_alerts_note_check CHECK (((note IS NULL) OR (length(note) <= 500)))
);


--
-- Name: xm_expiry_alert_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.xm_expiry_alert_detail WITH (security_invoker='true') AS
 SELECT a.id,
    a.outlet_id,
    a.product_id,
    a.batch,
    a.expiry_date,
    a.window_days,
    a.days_left,
    a.units_on_hand,
    a.daily_velocity,
    a.days_to_sell,
    a.consider_pulling,
    a.count_id,
    a.created_at,
    a.notified_at,
    a.acknowledged_at,
    a.acknowledged_by,
    a.note,
    o.name AS outlet_name,
    p.name AS product_name,
    p.sku,
    p.unit,
    ack.full_name AS acknowledged_by_name
   FROM (((public.xm_expiry_alerts a
     JOIN public.outlets o ON ((o.id = a.outlet_id)))
     JOIN public.products p ON ((p.id = a.product_id)))
     LEFT JOIN public.profiles ack ON ((ack.id = a.acknowledged_by)));


