    photo_path text,
    superseded_by uuid,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    CONSTRAINT xm_sales_void_reason_check CHECK (((void_reason IS NULL) OR ((length(btrim(void_reason)) >= 3) AND (length(btrim(void_reason)) <= 300))))
);


--
-- Name: xm_live_sale_lines; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.xm_live_sale_lines WITH (security_invoker='true') AS
 SELECT s.id AS sale_id,
    s.outlet_id,
    s.user_id,
    s.sale_date,
    s.created_at,
    l.product_id,
    l.units
   FROM (public.xm_sales s
     JOIN public.xm_sale_lines l ON ((l.sale_id = s.id)))
  WHERE ((s.superseded_by IS NULL) AND (s.voided_at IS NULL));


