    band text,
    finalised_at timestamp with time zone DEFAULT now() NOT NULL,
    finalised_by uuid,
    review_note text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    CONSTRAINT xm_monthly_grades_band_check CHECK ((band = ANY (ARRAY['Poor'::text, 'Average'::text, 'Strong'::text]))),
    CONSTRAINT xm_monthly_grades_month_check CHECK ((month = (date_trunc('month'::text, (month)::timestamp with time zone))::date)),
    CONSTRAINT xm_monthly_grades_review_note_check CHECK (((review_note IS NULL) OR (length(review_note) <= 1000)))
);


