-- Name: xm_reconciliations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xm_reconciliations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    count_id uuid NOT NULL,
    product_id uuid NOT NULL,
    previous_count_id uuid NOT NULL,
    previous_units integer NOT NULL,
    supplied_units integer NOT NULL,
    sold_units integer NOT NULL,
    expected_units integer NOT NULL,
    actual_units integer NOT NULL,
    variance_units integer NOT NULL,
    variance_pct numeric(8,2) NOT NULL,
    tolerance_pct numeric(5,2) NOT NULL,
    flagged boolean NOT NULL,
    flag_id uuid,
    computed_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: xm_reconciliation_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.xm_reconciliation_detail WITH (security_invoker='true') AS
 SELECT r.id,
    r.count_id,
    r.product_id,
    r.previous_count_id,
    r.previous_units,
    r.supplied_units,
    r.sold_units,
    r.expected_units,
    r.actual_units,
    r.variance_units,
    r.variance_pct,
    r.tolerance_pct,
    r.flagged,
    r.flag_id,
    r.computed_at,
    c.count_date,
    c.outlet_id,
    c.user_id,
    o.name AS outlet_name,
    p.name AS product_name,
    p.sku,
    pr.full_name AS staff_name
   FROM ((((public.xm_reconciliations r
     JOIN public.xm_counts c ON ((c.id = r.count_id)))
     JOIN public.outlets o ON ((o.id = c.outlet_id)))
     JOIN public.products p ON ((p.id = r.product_id)))
     LEFT JOIN public.profiles pr ON ((pr.id = c.user_id)));


--
-- Name: xm_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xm_settings (
    id boolean DEFAULT true NOT NULL,
    tolerance_pct numeric(5,2) DEFAULT 5 NOT NULL,
    weight_sales integer DEFAULT 40 NOT NULL,
    weight_accuracy integer DEFAULT 30 NOT NULL,
    weight_consistency integer DEFAULT 20 NOT NULL,
    weight_expiry integer DEFAULT 10 NOT NULL,
    band_poor_below integer DEFAULT 40 NOT NULL,
    band_strong_from integer DEFAULT 70 NOT NULL,
    alert_windows_days integer[] DEFAULT '{730,365,180,90,30}'::integer[] NOT NULL,
    velocity_days integer DEFAULT 30 NOT NULL,
    count_interval_days integer DEFAULT 7 NOT NULL,
    sales_grace_hours integer DEFAULT 12 NOT NULL,
    sales_photo_required boolean DEFAULT true NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT xm_settings_band_poor_below_check CHECK (((band_poor_below >= 1) AND (band_poor_below <= 99))),
    CONSTRAINT xm_settings_band_strong_from_check CHECK (((band_strong_from >= 2) AND (band_strong_from <= 100))),
    CONSTRAINT xm_settings_bands CHECK ((band_poor_below < band_strong_from)),
    CONSTRAINT xm_settings_count_interval_days_check CHECK (((count_interval_days >= 1) AND (count_interval_days <= 31))),
    CONSTRAINT xm_settings_id_check CHECK (id),
    CONSTRAINT xm_settings_sales_grace_hours_check CHECK (((sales_grace_hours >= 0) AND (sales_grace_hours <= 72))),
    CONSTRAINT xm_settings_tolerance_pct_check CHECK (((tolerance_pct >= (0)::numeric) AND (tolerance_pct <= (100)::numeric))),
    CONSTRAINT xm_settings_velocity_days_check CHECK (((velocity_days >= 7) AND (velocity_days <= 365))),
    CONSTRAINT xm_settings_weight_accuracy_check CHECK (((weight_accuracy >= 0) AND (weight_accuracy <= 100))),
    CONSTRAINT xm_settings_weight_consistency_check CHECK (((weight_consistency >= 0) AND (weight_consistency <= 100))),
    CONSTRAINT xm_settings_weight_expiry_check CHECK (((weight_expiry >= 0) AND (weight_expiry <= 100))),
    CONSTRAINT xm_settings_weight_sales_check CHECK (((weight_sales >= 0) AND (weight_sales <= 100))),
    CONSTRAINT xm_settings_weights CHECK (((((weight_sales + weight_accuracy) + weight_consistency) + weight_expiry) = 100)),
    CONSTRAINT xm_settings_windows CHECK ((((cardinality(alert_windows_days) >= 1) AND (cardinality(alert_windows_days) <= 10)) AND (0 < ALL (alert_windows_days)) AND (3650 >= ALL (alert_windows_days))))
);


