    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: xm_stock_on_hand; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.xm_stock_on_hand WITH (security_invoker='true') AS
 WITH latest AS (
         SELECT DISTINCT ON (c.outlet_id, l_1.product_id) c.outlet_id,
            l_1.product_id,
            c.id AS count_id,
            c.count_date
           FROM (public.xm_counts c
             JOIN public.xm_count_lines l_1 ON ((l_1.count_id = c.id)))
          WHERE (c.voided_at IS NULL)
          ORDER BY c.outlet_id, l_1.product_id, c.count_date DESC, c.created_at DESC
        )
 SELECT x.outlet_id,
    x.product_id,
    x.count_id,
    x.count_date,
    l.batch,
    l.expiry_date,
    l.on_shelf,
    l.in_backroom,
    (l.on_shelf + l.in_backroom) AS units
   FROM (latest x
     JOIN public.xm_count_lines l ON (((l.count_id = x.count_id) AND (l.product_id = x.product_id))));


