--
-- Name: xm_supplies; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xm_supplies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    outlet_id uuid NOT NULL,
    product_id uuid NOT NULL,
    quantity integer NOT NULL,
    batch text DEFAULT ''::text NOT NULL,
    expiry_date date,
    supplied_on date NOT NULL,
    note text,
    logged_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    cartons integer,
    units_per_carton integer,
    import_id uuid,
    CONSTRAINT xm_supplies_batch_check CHECK ((length(batch) <= 60)),
    CONSTRAINT xm_supplies_cartons_check CHECK (((cartons IS NULL) OR ((cartons >= 1) AND (cartons <= 100000)))),
    CONSTRAINT xm_supplies_note_check CHECK (((note IS NULL) OR (length(note) <= 500))),
    CONSTRAINT xm_supplies_quantity_check CHECK (((quantity >= 1) AND (quantity <= 1000000))),
    CONSTRAINT xm_supplies_units_per_carton_check CHECK (((units_per_carton IS NULL) OR ((units_per_carton >= 1) AND (units_per_carton <= 100000)))),
    CONSTRAINT xm_supplies_void_reason_check CHECK (((void_reason IS NULL) OR ((length(btrim(void_reason)) >= 3) AND (length(btrim(void_reason)) <= 300))))
);


--
-- Name: xm_supply_imports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.xm_supply_imports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    file_name text NOT NULL,
    file_kind text NOT NULL,
    read_by text NOT NULL,
    supplier text,
    invoice_no text,
    invoice_date date,
    rows_found integer DEFAULT 0 NOT NULL,
    rows_logged integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT xm_supply_imports_file_kind_check CHECK ((file_kind = ANY (ARRAY['csv'::text, 'xlsx'::text, 'pdf'::text, 'docx'::text]))),
    CONSTRAINT xm_supply_imports_file_name_check CHECK (((length(btrim(file_name)) >= 1) AND (length(btrim(file_name)) <= 200))),
    CONSTRAINT xm_supply_imports_invoice_no_check CHECK (((invoice_no IS NULL) OR (length(invoice_no) <= 100))),
    CONSTRAINT xm_supply_imports_read_by_check CHECK ((read_by = ANY (ARRAY['table'::text, 'claude'::text]))),
    CONSTRAINT xm_supply_imports_rows_found_check CHECK ((rows_found >= 0)),
    CONSTRAINT xm_supply_imports_rows_logged_check CHECK ((rows_logged >= 0)),
    CONSTRAINT xm_supply_imports_supplier_check CHECK (((supplier IS NULL) OR (length(supplier) <= 200)))
);


--
-- Name: xm_supply_detail; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.xm_supply_detail WITH (security_invoker='true') AS
 SELECT s.id,
    s.outlet_id,
    s.product_id,
    s.quantity,
    s.batch,
    s.expiry_date,
    s.supplied_on,
    s.note,
    s.logged_by,
    s.created_at,
    s.voided_at,
    s.voided_by,
    s.void_reason,
    s.cartons,
    s.units_per_carton,
    s.import_id,
    o.name AS outlet_name,
    p.name AS product_name,
    p.sku,
    p.unit,
    lb.full_name AS logged_by_name,
    vb.full_name AS voided_by_name,
    i.file_name AS import_file
   FROM (((((public.xm_supplies s
     JOIN public.outlets o ON ((o.id = s.outlet_id)))
     JOIN public.products p ON ((p.id = s.product_id)))
     LEFT JOIN public.profiles lb ON ((lb.id = s.logged_by)))
     LEFT JOIN public.profiles vb ON ((vb.id = s.voided_by)))
     LEFT JOIN public.xm_supply_imports i ON ((i.id = s.import_id)));


